INSERT INTO public.curriculum_clusters (id, domain_id, code, name, source, active) VALUES
    ('6.NS.A', '6.NS', '6.NS.A', '{"en":"Apply and extend previous understandings of multiplication and division to divide fractions by fractions.","es":"Aplicar y ampliar los conocimientos previos de multiplicación y división para dividir fracciones entre fracciones."}'::jsonb, '{"sourceId":"ccss","pages":[42,43]}'::jsonb, true),
    ('6.NS.B', '6.NS', '6.NS.B', '{"en":"Compute fluently with multi-digit numbers and find common factors and multiples.","es":"Calcular con fluidez con números de varias cifras y hallar factores y múltiplos comunes."}'::jsonb, '{"sourceId":"ccss","pages":[42,43]}'::jsonb, true),
    ('6.NS.C', '6.NS', '6.NS.C', '{"en":"Apply and extend previous understandings of numbers to the system of rational numbers.","es":"Aplicar y ampliar los conocimientos previos de los números al sistema de los números racionales."}'::jsonb, '{"sourceId":"ccss","pages":[42,43]}'::jsonb, true),
    ('7.NS.A', '7.NS', '7.NS.A', '{"en":"Apply and extend previous understandings of operations with fractions to add, subtract, multiply, and divide rational numbers.","es":"Aplicar y ampliar los conocimientos previos de operaciones con fracciones para sumar, restar, multiplicar y dividir números racionales."}'::jsonb, '{"sourceId":"ccss","pages":[48,49]}'::jsonb, true),
    ('8.NS.A', '8.NS', '8.NS.A', '{"en":"Know that there are numbers that are not rational, and approximate them by rational numbers.","es":"Saber que existen números que no son racionales y aproximarlos mediante números racionales."}'::jsonb, '{"sourceId":"ccss","pages":[54]}'::jsonb, true),
    ('HSN-RN.A', 'HSN-RN', 'HSN-RN.A', '{"en":"Extend the properties of exponents to rational exponents.","es":"Ampliar las propiedades de los exponentes a los exponentes racionales."}'::jsonb, '{"sourceId":"ccss","pages":[60]}'::jsonb, true),
    ('HSN-RN.B', 'HSN-RN', 'HSN-RN.B', '{"en":"Use properties of rational and irrational numbers.","es":"Utilizar las propiedades de los números racionales e irracionales."}'::jsonb, '{"sourceId":"ccss","pages":[60]}'::jsonb, true),
    ('HSN-Q.A', 'HSN-Q', 'HSN-Q.A', '{"en":"Reason quantitatively and use units to solve problems.","es":"Razonar cuantitativamente y utilizar unidades para resolver problemas."}'::jsonb, '{"sourceId":"ccss","pages":[60]}'::jsonb, true),
    ('HSN-CN.A', 'HSN-CN', 'HSN-CN.A', '{"en":"Perform arithmetic operations with complex numbers.","es":"Realizar operaciones aritméticas con números complejos."}'::jsonb, '{"sourceId":"ccss","pages":[60]}'::jsonb, true),
    ('HSN-CN.C', 'HSN-CN', 'HSN-CN.C', '{"en":"Use complex numbers in polynomial identities and equations.","es":"Utilizar números complejos en identidades polinómicas y ecuaciones."}'::jsonb, '{"sourceId":"ccss","pages":[60]}'::jsonb, true),
    ('6.RP.A', '6.RP', '6.RP.A', '{"en":"Understand ratio concepts and use ratio reasoning to solve problems.","es":"Comprender los conceptos de razón y utilizar el razonamiento con razones para resolver problemas."}'::jsonb, '{"sourceId":"ccss","pages":[42]}'::jsonb, true),
    ('6.EE.A', '6.EE', '6.EE.A', '{"en":"Apply and extend previous understandings of arithmetic to algebraic expressions.","es":"Aplicar y ampliar los conocimientos previos de aritmética a las expresiones algebraicas."}'::jsonb, '{"sourceId":"ccss","pages":[43,44]}'::jsonb, true),
    ('6.EE.B', '6.EE', '6.EE.B', '{"en":"Reason about and solve one-variable equations and inequalities.","es":"Razonar sobre ecuaciones e inecuaciones de una variable y resolverlas."}'::jsonb, '{"sourceId":"ccss","pages":[43,44]}'::jsonb, true),
    ('6.EE.C', '6.EE', '6.EE.C', '{"en":"Represent and analyze quantitative relationships between dependent and independent variables.","es":"Representar y analizar relaciones cuantitativas entre variables dependientes e independientes."}'::jsonb, '{"sourceId":"ccss","pages":[43,44]}'::jsonb, true),
    ('7.RP.A', '7.RP', '7.RP.A', '{"en":"Analyze proportional relationships and use them to solve real-world and mathematical problems.","es":"Analizar relaciones proporcionales y utilizarlas para resolver problemas de la vida real y matemáticos."}'::jsonb, '{"sourceId":"ccss","pages":[48]}'::jsonb, true),
    ('7.EE.A', '7.EE', '7.EE.A', '{"en":"Use properties of operations to generate equivalent expressions.","es":"Utilizar las propiedades de las operaciones para generar expresiones equivalentes."}'::jsonb, '{"sourceId":"ccss","pages":[49]}'::jsonb, true),
    ('7.EE.B', '7.EE', '7.EE.B', '{"en":"Solve real-life and mathematical problems using numerical and algebraic expressions and equations.","es":"Resolver problemas de la vida real y matemáticos mediante expresiones numéricas y algebraicas y ecuaciones."}'::jsonb, '{"sourceId":"ccss","pages":[49]}'::jsonb, true),
    ('8.EE.A', '8.EE', '8.EE.A', '{"en":"Work with radicals and integer exponents.","es":"Trabajar con radicales y exponentes enteros."}'::jsonb, '{"sourceId":"ccss","pages":[54,55]}'::jsonb, true),
    ('8.EE.B', '8.EE', '8.EE.B', '{"en":"Understand the connections between proportional relationships, lines, and linear equations.","es":"Comprender las conexiones entre relaciones proporcionales, rectas y ecuaciones lineales."}'::jsonb, '{"sourceId":"ccss","pages":[54,55]}'::jsonb, true),
    ('8.EE.C', '8.EE', '8.EE.C', '{"en":"Analyze and solve linear equations and pairs of simultaneous linear equations.","es":"Analizar y resolver ecuaciones lineales y pares de ecuaciones lineales simultáneas."}'::jsonb, '{"sourceId":"ccss","pages":[54,55]}'::jsonb, true),
    ('HSA-SSE.A', 'HSA-SSE', 'HSA-SSE.A', '{"en":"Interpret the structure of expressions.","es":"Interpretar la estructura de las expresiones."}'::jsonb, '{"sourceId":"ccss","pages":[64]}'::jsonb, true),
    ('HSA-SSE.B', 'HSA-SSE', 'HSA-SSE.B', '{"en":"Write expressions in equivalent forms to solve problems.","es":"Escribir expresiones en formas equivalentes para resolver problemas."}'::jsonb, '{"sourceId":"ccss","pages":[64]}'::jsonb, true),
    ('HSA-APR.A', 'HSA-APR', 'HSA-APR.A', '{"en":"Perform arithmetic operations on polynomials.","es":"Realizar operaciones aritméticas con polinomios."}'::jsonb, '{"sourceId":"ccss","pages":[64,65]}'::jsonb, true),
    ('HSA-CED.A', 'HSA-CED', 'HSA-CED.A', '{"en":"Create equations that describe numbers or relationships.","es":"Crear ecuaciones que describan números o relaciones."}'::jsonb, '{"sourceId":"ccss","pages":[65]}'::jsonb, true),
    ('HSA-REI.A', 'HSA-REI', 'HSA-REI.A', '{"en":"Understand solving equations as a process of reasoning and explain the reasoning.","es":"Comprender la resolución de ecuaciones como un proceso de razonamiento y explicar dicho razonamiento."}'::jsonb, '{"sourceId":"ccss","pages":[65,66]}'::jsonb, true),
    ('HSA-REI.B', 'HSA-REI', 'HSA-REI.B', '{"en":"Solve equations and inequalities in one variable.","es":"Resolver ecuaciones e inecuaciones de una variable."}'::jsonb, '{"sourceId":"ccss","pages":[65,66]}'::jsonb, true),
    ('HSA-REI.C', 'HSA-REI', 'HSA-REI.C', '{"en":"Solve systems of equations.","es":"Resolver sistemas de ecuaciones."}'::jsonb, '{"sourceId":"ccss","pages":[65,66]}'::jsonb, true),
    ('HSA-REI.D', 'HSA-REI', 'HSA-REI.D', '{"en":"Represent and solve equations and inequalities graphically.","es":"Representar y resolver gráficamente ecuaciones e inecuaciones."}'::jsonb, '{"sourceId":"ccss","pages":[65,66]}'::jsonb, true),
    ('8.F.A', '8.F', '8.F.A', '{"en":"Define, evaluate, and compare functions.","es":"Definir, evaluar y comparar funciones."}'::jsonb, '{"sourceId":"ccss","pages":[55]}'::jsonb, true),
    ('8.F.B', '8.F', '8.F.B', '{"en":"Use functions to model relationships between quantities.","es":"Utilizar funciones para modelar relaciones entre cantidades."}'::jsonb, '{"sourceId":"ccss","pages":[55]}'::jsonb, true),
    ('HSF-IF.A', 'HSF-IF', 'HSF-IF.A', '{"en":"Understand the concept of a function and use function notation.","es":"Comprender el concepto de función y utilizar la notación de funciones."}'::jsonb, '{"sourceId":"ccss","pages":[69,70]}'::jsonb, true),
    ('HSF-IF.B', 'HSF-IF', 'HSF-IF.B', '{"en":"Interpret functions that arise in applications in terms of the context.","es":"Interpretar las funciones que surgen en aplicaciones en términos del contexto."}'::jsonb, '{"sourceId":"ccss","pages":[69,70]}'::jsonb, true),
    ('HSF-IF.C', 'HSF-IF', 'HSF-IF.C', '{"en":"Analyze functions using different representations.","es":"Analizar funciones utilizando distintas representaciones."}'::jsonb, '{"sourceId":"ccss","pages":[69,70]}'::jsonb, true),
    ('HSF-BF.A', 'HSF-BF', 'HSF-BF.A', '{"en":"Build a function that models a relationship between two quantities.","es":"Construir una función que modele una relación entre dos cantidades."}'::jsonb, '{"sourceId":"ccss","pages":[70]}'::jsonb, true),
    ('HSF-BF.B', 'HSF-BF', 'HSF-BF.B', '{"en":"Build new functions from existing functions.","es":"Construir funciones nuevas a partir de funciones existentes."}'::jsonb, '{"sourceId":"ccss","pages":[70]}'::jsonb, true),
    ('HSF-LE.A', 'HSF-LE', 'HSF-LE.A', '{"en":"Construct and compare linear, quadratic, and exponential models and solve problems.","es":"Construir y comparar modelos lineales, cuadráticos y exponenciales y resolver problemas."}'::jsonb, '{"sourceId":"ccss","pages":[70,71]}'::jsonb, true),
    ('HSF-LE.B', 'HSF-LE', 'HSF-LE.B', '{"en":"Interpret expressions for functions in terms of the situation they model.","es":"Interpretar expresiones de funciones en términos de la situación que modelan."}'::jsonb, '{"sourceId":"ccss","pages":[70,71]}'::jsonb, true),
    ('HSF-TF.C', 'HSF-TF', 'HSF-TF.C', '{"en":"Prove and apply trigonometric identities.","es":"Demostrar y aplicar identidades trigonométricas."}'::jsonb, '{"sourceId":"ccss","pages":[71]}'::jsonb, true),
    ('6.G.A', '6.G', '6.G.A', '{"en":"Solve real-world and mathematical problems involving area, surface area, and volume.","es":"Resolver problemas de la vida real y matemáticos relacionados con áreas, áreas superficiales y volúmenes."}'::jsonb, '{"sourceId":"ccss","pages":[44,45]}'::jsonb, true),
    ('7.G.A', '7.G', '7.G.A', '{"en":"Draw, construct, and describe geometrical figures and describe the relationships between them.","es":"Dibujar, construir y describir figuras geométricas y las relaciones entre ellas."}'::jsonb, '{"sourceId":"ccss","pages":[49,50]}'::jsonb, true),
    ('7.G.B', '7.G', '7.G.B', '{"en":"Solve real-life and mathematical problems involving angle measure, area, surface area, and volume.","es":"Resolver problemas de la vida real y matemáticos sobre medidas de ángulos, áreas, áreas superficiales y volúmenes."}'::jsonb, '{"sourceId":"ccss","pages":[49,50]}'::jsonb, true),
    ('8.G.A', '8.G', '8.G.A', '{"en":"Understand congruence and similarity using physical models, transparencies, or geometry software.","es":"Comprender la congruencia y la semejanza mediante modelos físicos, transparencias o programas de geometría."}'::jsonb, '{"sourceId":"ccss","pages":[55,56]}'::jsonb, true),
    ('8.G.B', '8.G', '8.G.B', '{"en":"Understand and apply the Pythagorean Theorem.","es":"Comprender y aplicar el teorema de Pitágoras."}'::jsonb, '{"sourceId":"ccss","pages":[55,56]}'::jsonb, true),
    ('8.G.C', '8.G', '8.G.C', '{"en":"Solve real-world and mathematical problems involving volume of cylinders, cones, and spheres.","es":"Resolver problemas de la vida real y matemáticos sobre el volumen de cilindros, conos y esferas."}'::jsonb, '{"sourceId":"ccss","pages":[55,56]}'::jsonb, true),
    ('HSG-CO.A', 'HSG-CO', 'HSG-CO.A', '{"en":"Experiment with transformations in the plane.","es":"Experimentar con transformaciones en el plano."}'::jsonb, '{"sourceId":"ccss","pages":[76]}'::jsonb, true),
    ('HSG-CO.B', 'HSG-CO', 'HSG-CO.B', '{"en":"Understand congruence in terms of rigid motions.","es":"Comprender la congruencia en términos de movimientos rígidos."}'::jsonb, '{"sourceId":"ccss","pages":[76]}'::jsonb, true),
    ('HSG-CO.C', 'HSG-CO', 'HSG-CO.C', '{"en":"Prove geometric theorems.","es":"Demostrar teoremas geométricos."}'::jsonb, '{"sourceId":"ccss","pages":[76]}'::jsonb, true),
    ('HSG-CO.D', 'HSG-CO', 'HSG-CO.D', '{"en":"Make geometric constructions.","es":"Realizar construcciones geométricas."}'::jsonb, '{"sourceId":"ccss","pages":[76]}'::jsonb, true),
    ('HSG-SRT.A', 'HSG-SRT', 'HSG-SRT.A', '{"en":"Understand similarity in terms of similarity transformations.","es":"Comprender la semejanza en términos de transformaciones de semejanza."}'::jsonb, '{"sourceId":"ccss","pages":[77]}'::jsonb, true),
    ('HSG-SRT.B', 'HSG-SRT', 'HSG-SRT.B', '{"en":"Prove theorems involving similarity.","es":"Demostrar teoremas relacionados con la semejanza."}'::jsonb, '{"sourceId":"ccss","pages":[77]}'::jsonb, true),
    ('HSG-SRT.C', 'HSG-SRT', 'HSG-SRT.C', '{"en":"Define trigonometric ratios and solve problems involving right triangles.","es":"Definir razones trigonométricas y resolver problemas relacionados con triángulos rectángulos."}'::jsonb, '{"sourceId":"ccss","pages":[77]}'::jsonb, true),
    ('HSG-C.A', 'HSG-C', 'HSG-C.A', '{"en":"Understand and apply theorems about circles.","es":"Comprender y aplicar teoremas sobre circunferencias."}'::jsonb, '{"sourceId":"ccss","pages":[77,78]}'::jsonb, true),
    ('HSG-C.B', 'HSG-C', 'HSG-C.B', '{"en":"Find arc lengths and areas of sectors of circles.","es":"Hallar longitudes de arco y áreas de sectores circulares."}'::jsonb, '{"sourceId":"ccss","pages":[77,78]}'::jsonb, true),
    ('HSG-GPE.A', 'HSG-GPE', 'HSG-GPE.A', '{"en":"Translate between the geometric description and the equation for a conic section.","es":"Pasar de la descripción geométrica a la ecuación de una sección cónica y viceversa."}'::jsonb, '{"sourceId":"ccss","pages":[78]}'::jsonb, true),
    ('HSG-GPE.B', 'HSG-GPE', 'HSG-GPE.B', '{"en":"Use coordinates to prove simple geometric theorems algebraically.","es":"Utilizar coordenadas para demostrar algebraicamente teoremas geométricos sencillos."}'::jsonb, '{"sourceId":"ccss","pages":[78]}'::jsonb, true),
    ('HSG-GMD.A', 'HSG-GMD', 'HSG-GMD.A', '{"en":"Explain volume formulas and use them to solve problems.","es":"Explicar fórmulas de volumen y utilizarlas para resolver problemas."}'::jsonb, '{"sourceId":"ccss","pages":[78]}'::jsonb, true),
    ('6.SP.A', '6.SP', '6.SP.A', '{"en":"Develop understanding of statistical variability.","es":"Desarrollar la comprensión de la variabilidad estadística."}'::jsonb, '{"sourceId":"ccss","pages":[45]}'::jsonb, true),
    ('6.SP.B', '6.SP', '6.SP.B', '{"en":"Summarize and describe distributions.","es":"Resumir y describir distribuciones."}'::jsonb, '{"sourceId":"ccss","pages":[45]}'::jsonb, true),
    ('7.SP.A', '7.SP', '7.SP.A', '{"en":"Use random sampling to draw inferences about a population.","es":"Utilizar el muestreo aleatorio para extraer inferencias sobre una población."}'::jsonb, '{"sourceId":"ccss","pages":[50,51]}'::jsonb, true),
    ('7.SP.B', '7.SP', '7.SP.B', '{"en":"Draw informal comparative inferences about two populations.","es":"Extraer inferencias comparativas informales sobre dos poblaciones."}'::jsonb, '{"sourceId":"ccss","pages":[50,51]}'::jsonb, true),
    ('7.SP.C', '7.SP', '7.SP.C', '{"en":"Investigate chance processes and develop, use, and evaluate probability models.","es":"Investigar procesos aleatorios y desarrollar, utilizar y evaluar modelos de probabilidad."}'::jsonb, '{"sourceId":"ccss","pages":[50,51]}'::jsonb, true),
    ('8.SP.A', '8.SP', '8.SP.A', '{"en":"Investigate patterns of association in bivariate data.","es":"Investigar patrones de asociación en datos bivariantes."}'::jsonb, '{"sourceId":"ccss","pages":[56]}'::jsonb, true),
    ('HSS-ID.A', 'HSS-ID', 'HSS-ID.A', '{"en":"Summarize, represent, and interpret data on a single count or measurement variable.","es":"Resumir, representar e interpretar datos de una única variable de recuento o medición."}'::jsonb, '{"sourceId":"ccss","pages":[81]}'::jsonb, true),
    ('HSS-ID.B', 'HSS-ID', 'HSS-ID.B', '{"en":"Summarize, represent, and interpret data on two categorical and quantitative variables.","es":"Resumir, representar e interpretar datos de dos variables categóricas y cuantitativas."}'::jsonb, '{"sourceId":"ccss","pages":[81]}'::jsonb, true),
    ('HSS-ID.C', 'HSS-ID', 'HSS-ID.C', '{"en":"Interpret linear models.","es":"Interpretar modelos lineales."}'::jsonb, '{"sourceId":"ccss","pages":[81]}'::jsonb, true),
    ('HSS-CP.A', 'HSS-CP', 'HSS-CP.A', '{"en":"Understand independence and conditional probability and use them to interpret data.","es":"Comprender la independencia y la probabilidad condicionada y utilizarlas para interpretar datos."}'::jsonb, '{"sourceId":"ccss","pages":[82]}'::jsonb, true),
    ('HSS-CP.B', 'HSS-CP', 'HSS-CP.B', '{"en":"Use the rules of probability to compute probabilities of compound events in a uniform probability model.","es":"Utilizar las reglas de probabilidad para calcular probabilidades de sucesos compuestos en un modelo de probabilidad uniforme."}'::jsonb, '{"sourceId":"ccss","pages":[82]}'::jsonb, true),
    ('HSS-MD.B', 'HSS-MD', 'HSS-MD.B', '{"en":"Use probability to evaluate outcomes of decisions.","es":"Utilizar la probabilidad para evaluar los resultados de decisiones."}'::jsonb, '{"sourceId":"ccss","pages":[82,83]}'::jsonb, true)
INSERT INTO public.curriculum_standards (id, cluster_id, code, ccss_id, description, markers, source, notes, active) VALUES
    ('6.NS.A.1', '6.NS.A', '6.NS.1', 'CCSS.MATH.CONTENT.6.NS.A.1', '{"en":"Interpret and compute quotients of fractions, and solve word problems involving division of fractions by fractions, e.g., by using visual fraction models and equations to represent the problem. For example, create a story context for (2/3) ÷ (3/4) and use a visual fraction model to show the quotient; use the relationship between multiplication and division to explain that (2/3) ÷ (3/4) = 8/9 because 3/4 of 8/9 is 2/3. (In general, (a/b) ÷ (c/d) = ad/bc.) How much chocolate will each person get if 3 people share 1/2 lb of chocolate equally? How many 3/4-cup servings are in 2/3 of a cup of yogurt? How wide is a rectangular strip of land with length 3/4 mi and area 1/2 square mi?","es":"Interpretar y calcular cocientes de fracciones y resolver problemas de enunciado que impliquen dividir fracciones entre fracciones, por ejemplo, utilizando modelos visuales de fracciones y ecuaciones para representar el problema. Por ejemplo, crear una situación para (2/3) ÷ (3/4) y utilizar un modelo visual de fracciones para mostrar el cociente; utilizar la relación entre multiplicación y división para explicar que (2/3) ÷ (3/4) = 8/9 porque 3/4 de 8/9 es 2/3. (En general, (a/b) ÷ (c/d) = ad/bc). ¿Cuánto chocolate recibirá cada persona si 3 personas comparten por igual 1/2 libra de chocolate? ¿Cuántas raciones de 3/4 de taza hay en 2/3 de taza de yogur? ¿Qué anchura tiene una franja rectangular de terreno de 3/4 de milla de longitud y 1/2 milla cuadrada de superficie?"}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[42]}'::jsonb, '[]'::jsonb, true),
    ('6.NS.B.2', '6.NS.B', '6.NS.2', 'CCSS.MATH.CONTENT.6.NS.B.2', '{"en":"Fluently divide multi-digit numbers using the standard algorithm.","es":"Dividir con fluidez números de varias cifras utilizando el algoritmo convencional."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[42]}'::jsonb, '[]'::jsonb, true),
    ('6.NS.B.3', '6.NS.B', '6.NS.3', 'CCSS.MATH.CONTENT.6.NS.B.3', '{"en":"Fluently add, subtract, multiply, and divide multi-digit decimals using the standard algorithm for each operation.","es":"Sumar, restar, multiplicar y dividir con fluidez números decimales de varias cifras utilizando el algoritmo convencional de cada operación."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[42]}'::jsonb, '[]'::jsonb, true),
    ('6.NS.B.4', '6.NS.B', '6.NS.4', 'CCSS.MATH.CONTENT.6.NS.B.4', '{"en":"Find the greatest common factor of two whole numbers less than or equal to 100 and the least common multiple of two whole numbers less than or equal to 12. Use the distributive property to express a sum of two whole numbers 1-100 with a common factor as a multiple of a sum of two whole numbers with no common factor. For example, express 36 + 8 as 4 (9 + 2).","es":"Hallar el máximo común divisor de dos números enteros no negativos menores o iguales que 100 y el mínimo común múltiplo de dos números enteros no negativos menores o iguales que 12. Utilizar la propiedad distributiva para expresar una suma de dos números enteros entre 1 y 100 con un factor común como un múltiplo de una suma de dos números enteros sin factores comunes distintos de 1. Por ejemplo, expresar 36 + 8 como 4 (9 + 2)."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[42]}'::jsonb, '[]'::jsonb, true),
    ('6.NS.C.5', '6.NS.C', '6.NS.5', 'CCSS.MATH.CONTENT.6.NS.C.5', '{"en":"Understand that positive and negative numbers are used together to describe quantities having opposite directions or values (e.g., temperature above/below zero, elevation above/below sea level, credits/debits, positive/negative electric charge); use positive and negative numbers to represent quantities in real-world contexts, explaining the meaning of 0 in each situation.","es":"Comprender que los números positivos y negativos se utilizan conjuntamente para describir cantidades con direcciones o valores opuestos (por ejemplo, temperatura por encima o por debajo de cero, altura por encima o por debajo del nivel del mar, abonos y cargos, carga eléctrica positiva o negativa); utilizar números positivos y negativos para representar cantidades en contextos de la vida real y explicar el significado del 0 en cada situación."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[43]}'::jsonb, '[]'::jsonb, true),
    ('6.NS.C.6', '6.NS.C', '6.NS.6', 'CCSS.MATH.CONTENT.6.NS.C.6', '{"en":"Understand a rational number as a point on the number line. Extend number line diagrams and coordinate axes familiar from previous grades to represent points on the line and in the plane with negative number coordinates.","es":"Comprender un número racional como un punto de la recta numérica. Ampliar los diagramas de recta numérica y los ejes de coordenadas conocidos de cursos anteriores para representar puntos en la recta y en el plano con coordenadas negativas."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[43]}'::jsonb, '[]'::jsonb, true),
    ('6.NS.C.7', '6.NS.C', '6.NS.7', 'CCSS.MATH.CONTENT.6.NS.C.7', '{"en":"Understand ordering and absolute value of rational numbers.","es":"Comprender la ordenación y el valor absoluto de los números racionales."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[43]}'::jsonb, '[]'::jsonb, true),
    ('6.NS.C.8', '6.NS.C', '6.NS.8', 'CCSS.MATH.CONTENT.6.NS.C.8', '{"en":"Solve real-world and mathematical problems by graphing points in all four quadrants of the coordinate plane. Include use of coordinates and absolute value to find distances between points with the same first coordinate or the same second coordinate.","es":"Resolver problemas de la vida real y matemáticos representando puntos en los cuatro cuadrantes del plano de coordenadas. Incluir el uso de coordenadas y del valor absoluto para hallar distancias entre puntos que tengan la misma primera coordenada o la misma segunda coordenada."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[43]}'::jsonb, '[]'::jsonb, true),
    ('7.NS.A.1', '7.NS.A', '7.NS.1', 'CCSS.MATH.CONTENT.7.NS.A.1', '{"en":"Apply and extend previous understandings of addition and subtraction to add and subtract rational numbers; represent addition and subtraction on a horizontal or vertical number line diagram.","es":"Aplicar y ampliar los conocimientos previos de suma y resta para sumar y restar números racionales; representar la suma y la resta en una recta numérica horizontal o vertical."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[48]}'::jsonb, '[]'::jsonb, true),
    ('7.NS.A.2', '7.NS.A', '7.NS.2', 'CCSS.MATH.CONTENT.7.NS.A.2', '{"en":"Apply and extend previous understandings of multiplication and division and of fractions to multiply and divide rational numbers.","es":"Aplicar y ampliar los conocimientos previos de multiplicación, división y fracciones para multiplicar y dividir números racionales."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[48]}'::jsonb, '[]'::jsonb, true),
    ('7.NS.A.3', '7.NS.A', '7.NS.3', 'CCSS.MATH.CONTENT.7.NS.A.3', '{"en":"Solve real-world and mathematical problems involving the four operations with rational numbers.","es":"Resolver problemas de la vida real y matemáticos que impliquen las cuatro operaciones con números racionales."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[49]}'::jsonb, '[{"text":{"en":"Computations with rational numbers extend the rules for manipulating fractions to complex fractions.","es":"Los cálculos con números racionales amplían las reglas de operación con fracciones a las fracciones complejas."},"source":{"sourceId":"ccss","pages":[49]}}]'::jsonb, true),
    ('8.NS.A.1', '8.NS.A', '8.NS.1', 'CCSS.MATH.CONTENT.8.NS.A.1', '{"en":"Know that numbers that are not rational are called irrational. Understand informally that every number has a decimal expansion; for rational numbers show that the decimal expansion repeats eventually, and convert a decimal expansion which repeats eventually into a rational number.","es":"Saber que los números que no son racionales se llaman irracionales. Comprender informalmente que todo número tiene una expresión decimal; mostrar que, en los números racionales, la expresión decimal acaba repitiéndose periódicamente y convertir una expresión decimal periódica en un número racional."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[54]}'::jsonb, '[]'::jsonb, true),
    ('8.NS.A.2', '8.NS.A', '8.NS.2', 'CCSS.MATH.CONTENT.8.NS.A.2', '{"en":"Use rational approximations of irrational numbers to compare the size of irrational numbers, locate them approximately on a number line diagram, and estimate the value of expressions (e.g., pi^2). For example, by truncating the decimal expansion of √2, show that √2 is between 1 and 2, then between 1.4 and 1.5, and explain how to continue on to get better approximations.","es":"Utilizar aproximaciones racionales de números irracionales para comparar sus magnitudes, situarlos aproximadamente en una recta numérica y estimar el valor de expresiones (por ejemplo, pi^2). Por ejemplo, truncando la expresión decimal de √2, mostrar que √2 está entre 1 y 2, luego entre 1.4 y 1.5, y explicar cómo continuar para obtener mejores aproximaciones."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[54]}'::jsonb, '[]'::jsonb, true),
    ('HSN-RN.A.1', 'HSN-RN.A', 'N-RN.1', 'CCSS.MATH.CONTENT.HSN-RN.A.1', '{"en":"Explain how the definition of the meaning of rational exponents follows from extending the properties of integer exponents to those values, allowing for a notation for radicals in terms of rational exponents. For example, we define 5^(1/3) to be the cube root of 5 because we want (5^(1/3))^3 = 5^((1/3)*3) to hold, so (5^(1/3))^3 must equal 5.","es":"Explicar cómo la definición del significado de los exponentes racionales resulta de ampliar las propiedades de los exponentes enteros a esos valores, lo que permite expresar los radicales mediante exponentes racionales. Por ejemplo, se define 5^(1/3) como la raíz cúbica de 5 porque se desea que se cumpla (5^(1/3))^3 = 5^((1/3)*3), por lo que (5^(1/3))^3 debe ser igual a 5."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[60]}'::jsonb, '[]'::jsonb, true),
    ('HSN-RN.A.2', 'HSN-RN.A', 'N-RN.2', 'CCSS.MATH.CONTENT.HSN-RN.A.2', '{"en":"Rewrite expressions involving radicals and rational exponents using the properties of exponents.","es":"Reescribir expresiones que incluyan radicales y exponentes racionales utilizando las propiedades de los exponentes."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[60]}'::jsonb, '[]'::jsonb, true),
    ('HSN-RN.B.3', 'HSN-RN.B', 'N-RN.3', 'CCSS.MATH.CONTENT.HSN-RN.B.3', '{"en":"Explain why the sum or product of two rational numbers is rational; that the sum of a rational number and an irrational number is irrational; and that the product of a nonzero rational number and an irrational number is irrational.","es":"Explicar por qué la suma o el producto de dos números racionales es racional; por qué la suma de un número racional y uno irracional es irracional; y por qué el producto de un número racional distinto de cero y uno irracional es irracional."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[60]}'::jsonb, '[]'::jsonb, true),
    ('HSN-Q.A.1', 'HSN-Q.A', 'N-Q.1', 'CCSS.MATH.CONTENT.HSN-Q.A.1', '{"en":"Use units as a way to understand problems and to guide the solution of multi-step problems; choose and interpret units consistently in formulas; choose and interpret the scale and the origin in graphs and data displays.","es":"Utilizar las unidades para comprender problemas y orientar la resolución de problemas de varios pasos; elegir e interpretar las unidades de forma coherente en las fórmulas; elegir e interpretar la escala y el origen en gráficas y representaciones de datos."}'::jsonb, '{"modeling":true,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[60]}'::jsonb, '[]'::jsonb, true),
    ('HSN-Q.A.2', 'HSN-Q.A', 'N-Q.2', 'CCSS.MATH.CONTENT.HSN-Q.A.2', '{"en":"Define appropriate quantities for the purpose of descriptive modeling.","es":"Definir cantidades adecuadas para realizar modelado descriptivo."}'::jsonb, '{"modeling":true,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[60]}'::jsonb, '[]'::jsonb, true),
    ('HSN-Q.A.3', 'HSN-Q.A', 'N-Q.3', 'CCSS.MATH.CONTENT.HSN-Q.A.3', '{"en":"Choose a level of accuracy appropriate to limitations on measurement when reporting quantities.","es":"Elegir un grado de precisión adecuado a las limitaciones de la medición al comunicar cantidades."}'::jsonb, '{"modeling":true,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[60]}'::jsonb, '[]'::jsonb, true),
    ('HSN-CN.A.1', 'HSN-CN.A', 'N-CN.1', 'CCSS.MATH.CONTENT.HSN-CN.A.1', '{"en":"Know there is a complex number i such that i^2 = -1, and every complex number has the form a + bi with a and b real.","es":"Saber que existe un número complejo i tal que i^2 = -1 y que todo número complejo tiene la forma a + bi, con a y b reales."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[60]}'::jsonb, '[]'::jsonb, true),
    ('HSN-CN.A.2', 'HSN-CN.A', 'N-CN.2', 'CCSS.MATH.CONTENT.HSN-CN.A.2', '{"en":"Use the relation i^2 = -1 and the commutative, associative, and distributive properties to add, subtract, and multiply complex numbers.","es":"Utilizar la relación i^2 = -1 y las propiedades conmutativa, asociativa y distributiva para sumar, restar y multiplicar números complejos."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[60]}'::jsonb, '[]'::jsonb, true),
    ('HSN-CN.C.7', 'HSN-CN.C', 'N-CN.7', 'CCSS.MATH.CONTENT.HSN-CN.C.7', '{"en":"Solve quadratic equations with real coefficients that have complex solutions.","es":"Resolver ecuaciones cuadráticas con coeficientes reales que tengan soluciones complejas."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[60]}'::jsonb, '[]'::jsonb, true),
    ('HSN-CN.C.8', 'HSN-CN.C', 'N-CN.8', 'CCSS.MATH.CONTENT.HSN-CN.C.8', '{"en":"Extend polynomial identities to the complex numbers. For example, rewrite x^2 + 4 as (x + 2i)(x - 2i).","es":"Ampliar las identidades polinómicas a los números complejos. Por ejemplo, reescribir x^2 + 4 como (x + 2i)(x - 2i)."}'::jsonb, '{"modeling":false,"plus":true}'::jsonb, '{"sourceId":"ccss","pages":[60]}'::jsonb, '[]'::jsonb, true),
    ('HSN-CN.C.9', 'HSN-CN.C', 'N-CN.9', 'CCSS.MATH.CONTENT.HSN-CN.C.9', '{"en":"Know the Fundamental Theorem of Algebra; show that it is true for quadratic polynomials.","es":"Conocer el teorema fundamental del álgebra y mostrar que se cumple para polinomios cuadráticos."}'::jsonb, '{"modeling":false,"plus":true}'::jsonb, '{"sourceId":"ccss","pages":[60]}'::jsonb, '[]'::jsonb, true),
    ('6.RP.A.1', '6.RP.A', '6.RP.1', 'CCSS.MATH.CONTENT.6.RP.A.1', '{"en":"Understand the concept of a ratio and use ratio language to describe a ratio relationship between two quantities. For example, \"The ratio of wings to beaks in the bird house at the zoo was 2:1, because for every 2 wings there was 1 beak.\" \"For every vote candidate A received, candidate C received nearly three votes.\"","es":"Comprender el concepto de razón y utilizar el lenguaje de razones para describir una relación entre dos cantidades. Por ejemplo: «La razón entre alas y picos en la pajarera del zoo era de 2:1, porque por cada 2 alas había 1 pico». «Por cada voto que recibió el candidato A, el candidato C recibió casi tres votos»."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[42]}'::jsonb, '[]'::jsonb, true),
    ('6.RP.A.2', '6.RP.A', '6.RP.2', 'CCSS.MATH.CONTENT.6.RP.A.2', '{"en":"Understand the concept of a unit rate a/b associated with a ratio a:b with b ≠ 0, and use rate language in the context of a ratio relationship. For example, \"This recipe has a ratio of 3 cups of flour to 4 cups of sugar, so there is 3/4 cup of flour for each cup of sugar.\" \"We paid $75 for 15 hamburgers, which is a rate of $5 per hamburger.\"","es":"Comprender el concepto de tasa unitaria a/b asociada a una razón a:b con b ≠ 0, y utilizar el lenguaje de tasas en el contexto de una relación de razón. Por ejemplo: «Esta receta tiene una razón de 3 tazas de harina por 4 tazas de azúcar, por lo que hay 3/4 de taza de harina por cada taza de azúcar». «Pagamos 75 dólares por 15 hamburguesas, lo que supone una tasa de 5 dólares por hamburguesa»."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[42]}'::jsonb, '[{"text":{"en":"Expectations for unit rates in this grade are limited to non-complex fractions.","es":"Las expectativas sobre tasas unitarias en este curso se limitan a fracciones no complejas."},"source":{"sourceId":"ccss","pages":[42]}}]'::jsonb, true),
    ('6.RP.A.3', '6.RP.A', '6.RP.3', 'CCSS.MATH.CONTENT.6.RP.A.3', '{"en":"Use ratio and rate reasoning to solve real-world and mathematical problems, e.g., by reasoning about tables of equivalent ratios, tape diagrams, double number line diagrams, or equations.","es":"Utilizar el razonamiento con razones y tasas para resolver problemas de la vida real y matemáticos, por ejemplo, razonando sobre tablas de razones equivalentes, diagramas de barras, diagramas de doble recta numérica o ecuaciones."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[42]}'::jsonb, '[]'::jsonb, true),
    ('6.EE.A.1', '6.EE.A', '6.EE.1', 'CCSS.MATH.CONTENT.6.EE.A.1', '{"en":"Write and evaluate numerical expressions involving whole-number exponents.","es":"Escribir y evaluar expresiones numéricas que incluyan exponentes enteros no negativos."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[43]}'::jsonb, '[]'::jsonb, true),
    ('6.EE.A.2', '6.EE.A', '6.EE.2', 'CCSS.MATH.CONTENT.6.EE.A.2', '{"en":"Write, read, and evaluate expressions in which letters stand for numbers.","es":"Escribir, leer y evaluar expresiones en las que las letras representan números."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[43]}'::jsonb, '[]'::jsonb, true),
    ('6.EE.A.3', '6.EE.A', '6.EE.3', 'CCSS.MATH.CONTENT.6.EE.A.3', '{"en":"Apply the properties of operations to generate equivalent expressions. For example, apply the distributive property to the expression 3 (2 + x) to produce the equivalent expression 6 + 3x; apply the distributive property to the expression 24x + 18y to produce the equivalent expression 6 (4x + 3y); apply properties of operations to y + y + y to produce the equivalent expression 3y.","es":"Aplicar las propiedades de las operaciones para generar expresiones equivalentes. Por ejemplo, aplicar la propiedad distributiva a la expresión 3 (2 + x) para obtener la expresión equivalente 6 + 3x; aplicar la propiedad distributiva a la expresión 24x + 18y para obtener la expresión equivalente 6 (4x + 3y); aplicar las propiedades de las operaciones a y + y + y para obtener la expresión equivalente 3y."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[44]}'::jsonb, '[]'::jsonb, true),
    ('6.EE.A.4', '6.EE.A', '6.EE.4', 'CCSS.MATH.CONTENT.6.EE.A.4', '{"en":"Identify when two expressions are equivalent (i.e., when the two expressions name the same number regardless of which value is substituted into them). For example, the expressions y + y + y and 3y are equivalent because they name the same number regardless of which number y stands for.","es":"Identificar cuándo dos expresiones son equivalentes (es decir, cuándo representan el mismo número independientemente del valor que se sustituya en ellas). Por ejemplo, las expresiones y + y + y y 3y son equivalentes porque representan el mismo número, sea cual sea el número que represente y."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[44]}'::jsonb, '[]'::jsonb, true),
    ('6.EE.B.5', '6.EE.B', '6.EE.5', 'CCSS.MATH.CONTENT.6.EE.B.5', '{"en":"Understand solving an equation or inequality as a process of answering a question: which values from a specified set, if any, make the equation or inequality true? Use substitution to determine whether a given number in a specified set makes an equation or inequality true.","es":"Comprender la resolución de una ecuación o inecuación como un proceso para responder a una pregunta: ¿qué valores de un conjunto determinado, si los hay, hacen verdadera la ecuación o inecuación? Utilizar la sustitución para determinar si un número dado de un conjunto especificado hace verdadera una ecuación o inecuación."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[44]}'::jsonb, '[]'::jsonb, true),
    ('6.EE.B.6', '6.EE.B', '6.EE.6', 'CCSS.MATH.CONTENT.6.EE.B.6', '{"en":"Use variables to represent numbers and write expressions when solving a real-world or mathematical problem; understand that a variable can represent an unknown number, or, depending on the purpose at hand, any number in a specified set.","es":"Utilizar variables para representar números y escribir expresiones al resolver un problema de la vida real o matemático; comprender que una variable puede representar un número desconocido o, según el propósito, cualquier número de un conjunto especificado."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[44]}'::jsonb, '[]'::jsonb, true),
    ('6.EE.B.7', '6.EE.B', '6.EE.7', 'CCSS.MATH.CONTENT.6.EE.B.7', '{"en":"Solve real-world and mathematical problems by writing and solving equations of the form x + p = q and px = q for cases in which p, q and x are all nonnegative rational numbers.","es":"Resolver problemas de la vida real y matemáticos escribiendo y resolviendo ecuaciones de la forma x + p = q y px = q en los casos en que p, q y x sean números racionales no negativos."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[44]}'::jsonb, '[]'::jsonb, true),
    ('6.EE.B.8', '6.EE.B', '6.EE.8', 'CCSS.MATH.CONTENT.6.EE.B.8', '{"en":"Write an inequality of the form x > c or x < c to represent a constraint or condition in a real-world or mathematical problem. Recognize that inequalities of the form x > c or x < c have infinitely many solutions; represent solutions of such inequalities on number line diagrams.","es":"Escribir una inecuación de la forma x > c o x < c para representar una restricción o condición de un problema de la vida real o matemático. Reconocer que las inecuaciones de la forma x > c o x < c tienen infinitas soluciones; representar sus soluciones en rectas numéricas."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[44]}'::jsonb, '[]'::jsonb, true),
    ('6.EE.C.9', '6.EE.C', '6.EE.9', 'CCSS.MATH.CONTENT.6.EE.C.9', '{"en":"Use variables to represent two quantities in a real-world problem that change in relationship to one another; write an equation to express one quantity, thought of as the dependent variable, in terms of the other quantity, thought of as the independent variable. Analyze the relationship between the dependent and independent variables using graphs and tables, and relate these to the equation. For example, in a problem involving motion at constant speed, list and graph ordered pairs of distances and times, and write the equation d = 65t to represent the relationship between distance and time.","es":"Utilizar variables para representar dos cantidades de un problema real que cambian en relación mutua; escribir una ecuación para expresar una cantidad, considerada la variable dependiente, en términos de la otra, considerada la variable independiente. Analizar la relación entre la variable dependiente y la independiente mediante gráficas y tablas y relacionarlas con la ecuación. Por ejemplo, en un problema de movimiento a velocidad constante, enumerar y representar pares ordenados de distancias y tiempos, y escribir la ecuación d = 65t para representar la relación entre distancia y tiempo."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[44]}'::jsonb, '[]'::jsonb, true),
    ('7.RP.A.1', '7.RP.A', '7.RP.1', 'CCSS.MATH.CONTENT.7.RP.A.1', '{"en":"Compute unit rates associated with ratios of fractions, including ratios of lengths, areas and other quantities measured in like or different units. For example, if a person walks 1/2 mile in each 1/4 hour, compute the unit rate as the complex fraction (1/2)/(1/4) miles per hour, equivalently 2 miles per hour.","es":"Calcular tasas unitarias asociadas a razones de fracciones, incluidas razones de longitudes, áreas y otras cantidades medidas en unidades iguales o diferentes. Por ejemplo, si una persona camina 1/2 milla en cada 1/4 de hora, calcular la tasa unitaria como la fracción compleja (1/2)/(1/4) millas por hora, equivalente a 2 millas por hora."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[48]}'::jsonb, '[]'::jsonb, true),
    ('7.RP.A.2', '7.RP.A', '7.RP.2', 'CCSS.MATH.CONTENT.7.RP.A.2', '{"en":"Recognize and represent proportional relationships between quantities.","es":"Reconocer y representar relaciones proporcionales entre cantidades."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[48]}'::jsonb, '[]'::jsonb, true),
    ('7.RP.A.3', '7.RP.A', '7.RP.3', 'CCSS.MATH.CONTENT.7.RP.A.3', '{"en":"Use proportional relationships to solve multistep ratio and percent problems. Examples: simple interest, tax, markups and markdowns, gratuities and commissions, fees, percent increase and decrease, percent error.","es":"Utilizar relaciones proporcionales para resolver problemas de razones y porcentajes de varios pasos. Ejemplos: interés simple, impuestos, recargos y rebajas, propinas y comisiones, tarifas, aumentos y disminuciones porcentuales y error porcentual."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[48]}'::jsonb, '[]'::jsonb, true),
    ('7.EE.A.1', '7.EE.A', '7.EE.1', 'CCSS.MATH.CONTENT.7.EE.A.1', '{"en":"Apply properties of operations as strategies to add, subtract, factor, and expand linear expressions with rational coefficients.","es":"Aplicar las propiedades de las operaciones como estrategias para sumar, restar, factorizar y desarrollar expresiones lineales con coeficientes racionales."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[49]}'::jsonb, '[]'::jsonb, true),
    ('7.EE.A.2', '7.EE.A', '7.EE.2', 'CCSS.MATH.CONTENT.7.EE.A.2', '{"en":"Understand that rewriting an expression in different forms in a problem context can shed light on the problem and how the quantities in it are related. For example, a + 0.05a = 1.05a means that \"increase by 5%\" is the same as \"multiply by 1.05.\"","es":"Comprender que reescribir una expresión de distintas formas en el contexto de un problema puede aclarar el problema y las relaciones entre sus cantidades. Por ejemplo, a + 0.05a = 1.05a significa que «aumentar un 5 %» es lo mismo que «multiplicar por 1.05»."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[49]}'::jsonb, '[]'::jsonb, true),
    ('7.EE.B.3', '7.EE.B', '7.EE.3', 'CCSS.MATH.CONTENT.7.EE.B.3', '{"en":"Solve multi-step real-life and mathematical problems posed with positive and negative rational numbers in any form (whole numbers, fractions, and decimals), using tools strategically. Apply properties of operations to calculate with numbers in any form; convert between forms as appropriate; and assess the reasonableness of answers using mental computation and estimation strategies. For example: If a woman making $25 an hour gets a 10% raise, she will make an additional 1/10 of her salary an hour, or $2.50, for a new salary of $27.50. If you want to place a towel bar 9 3/4 inches long in the center of a door that is 27 1/2 inches wide, you will need to place the bar about 9 inches from each edge; this estimate can be used as a check on the exact computation.","es":"Resolver problemas de la vida real y matemáticos de varios pasos planteados con números racionales positivos y negativos en cualquier forma (enteros no negativos, fracciones y decimales), utilizando herramientas de forma estratégica. Aplicar las propiedades de las operaciones para calcular con números en cualquier forma; convertir entre formas según convenga; y evaluar si las respuestas son razonables mediante cálculo mental y estrategias de estimación. Por ejemplo: si una mujer que gana 25 dólares por hora recibe un aumento del 10 %, ganará 1/10 adicional de su salario por hora, es decir, 2.50 dólares, y su nuevo salario será de 27.50 dólares. Si se desea colocar un toallero de 9 3/4 pulgadas de longitud en el centro de una puerta de 27 1/2 pulgadas de anchura, deberá situarse a unas 9 pulgadas de cada borde; esta estimación permite comprobar el cálculo exacto."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[49]}'::jsonb, '[]'::jsonb, true),
    ('7.EE.B.4', '7.EE.B', '7.EE.4', 'CCSS.MATH.CONTENT.7.EE.B.4', '{"en":"Use variables to represent quantities in a real-world or mathematical problem, and construct simple equations and inequalities to solve problems by reasoning about the quantities.","es":"Utilizar variables para representar cantidades en un problema de la vida real o matemático y construir ecuaciones e inecuaciones sencillas para resolver problemas razonando sobre las cantidades."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[49]}'::jsonb, '[]'::jsonb, true),
    ('8.EE.A.1', '8.EE.A', '8.EE.1', 'CCSS.MATH.CONTENT.8.EE.A.1', '{"en":"Know and apply the properties of integer exponents to generate equivalent numerical expressions. For example, 3^2 x 3^-5 = 3^-3 = 1/3^3 = 1/27.","es":"Conocer y aplicar las propiedades de los exponentes enteros para generar expresiones numéricas equivalentes. Por ejemplo, 3^2 × 3^-5 = 3^-3 = 1/3^3 = 1/27."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[54]}'::jsonb, '[]'::jsonb, true),
    ('8.EE.A.2', '8.EE.A', '8.EE.2', 'CCSS.MATH.CONTENT.8.EE.A.2', '{"en":"Use square root and cube root symbols to represent solutions to equations of the form x^2 = p and x^3 = p, where p is a positive rational number. Evaluate square roots of small perfect squares and cube roots of small perfect cubes. Know that √2 is irrational.","es":"Utilizar los símbolos de raíz cuadrada y raíz cúbica para representar soluciones de ecuaciones de la forma x^2 = p y x^3 = p, donde p es un número racional positivo. Calcular raíces cuadradas de cuadrados perfectos pequeños y raíces cúbicas de cubos perfectos pequeños. Saber que √2 es irracional."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[54]}'::jsonb, '[]'::jsonb, true),
    ('8.EE.A.3', '8.EE.A', '8.EE.3', 'CCSS.MATH.CONTENT.8.EE.A.3', '{"en":"Use numbers expressed in the form of a single digit times an integer power of 10 to estimate very large or very small quantities, and to express how many times as much one is than the other. For example, estimate the population of the United States as 3 x 10^8 and the population of the world as 7 x 10^9, and determine that the world population is more than 20 times larger.","es":"Utilizar números expresados como una sola cifra multiplicada por una potencia entera de 10 para estimar cantidades muy grandes o muy pequeñas y expresar cuántas veces una cantidad es mayor que otra. Por ejemplo, estimar la población de Estados Unidos como 3 × 10^8 y la población mundial como 7 × 10^9, y determinar que la población mundial es más de 20 veces mayor."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[54]}'::jsonb, '[]'::jsonb, true),
    ('8.EE.A.4', '8.EE.A', '8.EE.4', 'CCSS.MATH.CONTENT.8.EE.A.4', '{"en":"Perform operations with numbers expressed in scientific notation, including problems where both decimal and scientific notation are used. Use scientific notation and choose units of appropriate size for measurements of very large or very small quantities (e.g., use millimeters per year for seafloor spreading). Interpret scientific notation that has been generated by technology.","es":"Realizar operaciones con números expresados en notación científica, incluidos problemas en los que se utilicen tanto notación decimal como científica. Utilizar la notación científica y elegir unidades de tamaño adecuado para medir cantidades muy grandes o muy pequeñas (por ejemplo, milímetros por año para la expansión del fondo oceánico). Interpretar la notación científica generada por herramientas tecnológicas."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[54]}'::jsonb, '[]'::jsonb, true),
    ('8.EE.B.5', '8.EE.B', '8.EE.5', 'CCSS.MATH.CONTENT.8.EE.B.5', '{"en":"Graph proportional relationships, interpreting the unit rate as the slope of the graph. Compare two different proportional relationships represented in different ways. For example, compare a distance-time graph to a distance-time equation to determine which of two moving objects has greater speed.","es":"Representar gráficamente relaciones proporcionales, interpretando la tasa unitaria como la pendiente de la gráfica. Comparar dos relaciones proporcionales diferentes representadas de distintas formas. Por ejemplo, comparar una gráfica de distancia y tiempo con una ecuación de distancia y tiempo para determinar cuál de dos objetos en movimiento tiene mayor velocidad."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[54]}'::jsonb, '[]'::jsonb, true),
    ('8.EE.B.6', '8.EE.B', '8.EE.6', 'CCSS.MATH.CONTENT.8.EE.B.6', '{"en":"Use similar triangles to explain why the slope m is the same between any two distinct points on a non-vertical line in the coordinate plane; derive the equation y = mx for a line through the origin and the equation y = mx + b for a line intercepting the vertical axis at b.","es":"Utilizar triángulos semejantes para explicar por qué la pendiente m es la misma entre cualesquiera dos puntos distintos de una recta no vertical del plano de coordenadas; deducir la ecuación y = mx de una recta que pasa por el origen y la ecuación y = mx + b de una recta que corta el eje vertical en b."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[54]}'::jsonb, '[]'::jsonb, true),
    ('8.EE.C.7', '8.EE.C', '8.EE.7', 'CCSS.MATH.CONTENT.8.EE.C.7', '{"en":"Solve linear equations in one variable.","es":"Resolver ecuaciones lineales de una variable."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[54]}'::jsonb, '[]'::jsonb, true),
    ('8.EE.C.8', '8.EE.C', '8.EE.8', 'CCSS.MATH.CONTENT.8.EE.C.8', '{"en":"Analyze and solve pairs of simultaneous linear equations.","es":"Analizar y resolver pares de ecuaciones lineales simultáneas."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[55]}'::jsonb, '[]'::jsonb, true),
    ('HSA-SSE.A.1', 'HSA-SSE.A', 'A-SSE.1', 'CCSS.MATH.CONTENT.HSA-SSE.A.1', '{"en":"Interpret expressions that represent a quantity in terms of its context.","es":"Interpretar expresiones que representan una cantidad en términos de su contexto."}'::jsonb, '{"modeling":true,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[64]}'::jsonb, '[]'::jsonb, true),
    ('HSA-SSE.A.2', 'HSA-SSE.A', 'A-SSE.2', 'CCSS.MATH.CONTENT.HSA-SSE.A.2', '{"en":"Use the structure of an expression to identify ways to rewrite it. For example, see x^4 - y^4 as (x^2)^2 - (y^2)^2, thus recognizing it as a difference of squares that can be factored as (x^2 - y^2)(x^2 + y^2).","es":"Utilizar la estructura de una expresión para identificar formas de reescribirla. Por ejemplo, considerar x^4 - y^4 como (x^2)^2 - (y^2)^2 y reconocer así una diferencia de cuadrados que puede factorizarse como (x^2 - y^2)(x^2 + y^2)."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[64]}'::jsonb, '[]'::jsonb, true),
    ('HSA-SSE.B.3', 'HSA-SSE.B', 'A-SSE.3', 'CCSS.MATH.CONTENT.HSA-SSE.B.3', '{"en":"Choose and produce an equivalent form of an expression to reveal and explain properties of the quantity represented by the expression.","es":"Elegir y producir una forma equivalente de una expresión para revelar y explicar propiedades de la cantidad que representa."}'::jsonb, '{"modeling":true,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[64]}'::jsonb, '[]'::jsonb, true),
    ('HSA-APR.A.1', 'HSA-APR.A', 'A-APR.1', 'CCSS.MATH.CONTENT.HSA-APR.A.1', '{"en":"Understand that polynomials form a system analogous to the integers, namely, they are closed under the operations of addition, subtraction, and multiplication; add, subtract, and multiply polynomials.","es":"Comprender que los polinomios forman un sistema análogo al de los números enteros, es decir, cerrado bajo las operaciones de suma, resta y multiplicación; sumar, restar y multiplicar polinomios."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[64]}'::jsonb, '[]'::jsonb, true),
    ('HSA-CED.A.1', 'HSA-CED.A', 'A-CED.1', 'CCSS.MATH.CONTENT.HSA-CED.A.1', '{"en":"Create equations and inequalities in one variable and use them to solve problems. Include equations arising from linear and quadratic functions, and simple rational and exponential functions.","es":"Crear ecuaciones e inecuaciones de una variable y utilizarlas para resolver problemas. Incluir ecuaciones procedentes de funciones lineales y cuadráticas y de funciones racionales y exponenciales sencillas."}'::jsonb, '{"modeling":true,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[65]}'::jsonb, '[]'::jsonb, true),
    ('HSA-CED.A.2', 'HSA-CED.A', 'A-CED.2', 'CCSS.MATH.CONTENT.HSA-CED.A.2', '{"en":"Create equations in two or more variables to represent relationships between quantities; graph equations on coordinate axes with labels and scales.","es":"Crear ecuaciones de dos o más variables para representar relaciones entre cantidades; representar las ecuaciones en ejes de coordenadas con etiquetas y escalas."}'::jsonb, '{"modeling":true,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[65]}'::jsonb, '[]'::jsonb, true),
    ('HSA-CED.A.3', 'HSA-CED.A', 'A-CED.3', 'CCSS.MATH.CONTENT.HSA-CED.A.3', '{"en":"Represent constraints by equations or inequalities, and by systems of equations and/or inequalities, and interpret solutions as viable or non-viable options in a modeling context. For example, represent inequalities describing nutritional and cost constraints on combinations of different foods.","es":"Representar restricciones mediante ecuaciones o inecuaciones y mediante sistemas de ecuaciones o inecuaciones, e interpretar las soluciones como opciones viables o no viables en un contexto de modelado. Por ejemplo, representar inecuaciones que describan restricciones nutricionales y de coste para combinaciones de distintos alimentos."}'::jsonb, '{"modeling":true,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[65]}'::jsonb, '[]'::jsonb, true),
    ('HSA-CED.A.4', 'HSA-CED.A', 'A-CED.4', 'CCSS.MATH.CONTENT.HSA-CED.A.4', '{"en":"Rearrange formulas to highlight a quantity of interest, using the same reasoning as in solving equations. For example, rearrange Ohm''s law V = IR to highlight resistance R.","es":"Reordenar fórmulas para despejar una cantidad de interés utilizando el mismo razonamiento que al resolver ecuaciones. Por ejemplo, reordenar la ley de Ohm V = IR para despejar la resistencia R."}'::jsonb, '{"modeling":true,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[65]}'::jsonb, '[]'::jsonb, true),
    ('HSA-REI.A.1', 'HSA-REI.A', 'A-REI.1', 'CCSS.MATH.CONTENT.HSA-REI.A.1', '{"en":"Explain each step in solving a simple equation as following from the equality of numbers asserted at the previous step, starting from the assumption that the original equation has a solution. Construct a viable argument to justify a solution method.","es":"Explicar cada paso de la resolución de una ecuación sencilla como consecuencia de la igualdad de números afirmada en el paso anterior, partiendo de la suposición de que la ecuación original tiene solución. Construir un argumento válido para justificar un método de resolución."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[65]}'::jsonb, '[]'::jsonb, true),
    ('HSA-REI.B.3', 'HSA-REI.B', 'A-REI.3', 'CCSS.MATH.CONTENT.HSA-REI.B.3', '{"en":"Solve linear equations and inequalities in one variable, including equations with coefficients represented by letters.","es":"Resolver ecuaciones e inecuaciones lineales de una variable, incluidas ecuaciones con coeficientes representados por letras."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[65]}'::jsonb, '[]'::jsonb, true),
    ('HSA-REI.B.4', 'HSA-REI.B', 'A-REI.4', 'CCSS.MATH.CONTENT.HSA-REI.B.4', '{"en":"Solve quadratic equations in one variable.","es":"Resolver ecuaciones cuadráticas de una variable."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[65]}'::jsonb, '[]'::jsonb, true),
    ('HSA-REI.C.5', 'HSA-REI.C', 'A-REI.5', 'CCSS.MATH.CONTENT.HSA-REI.C.5', '{"en":"Prove that, given a system of two equations in two variables, replacing one equation by the sum of that equation and a multiple of the other produces a system with the same solutions.","es":"Demostrar que, dado un sistema de dos ecuaciones con dos variables, sustituir una ecuación por la suma de esa ecuación y un múltiplo de la otra produce un sistema con las mismas soluciones."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[65]}'::jsonb, '[]'::jsonb, true),
    ('HSA-REI.C.6', 'HSA-REI.C', 'A-REI.6', 'CCSS.MATH.CONTENT.HSA-REI.C.6', '{"en":"Solve systems of linear equations exactly and approximately (e.g., with graphs), focusing on pairs of linear equations in two variables.","es":"Resolver sistemas de ecuaciones lineales de forma exacta y aproximada (por ejemplo, mediante gráficas), centrándose en pares de ecuaciones lineales con dos variables."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[66]}'::jsonb, '[]'::jsonb, true),
    ('HSA-REI.C.7', 'HSA-REI.C', 'A-REI.7', 'CCSS.MATH.CONTENT.HSA-REI.C.7', '{"en":"Solve a simple system consisting of a linear equation and a quadratic equation in two variables algebraically and graphically. For example, find the points of intersection between the line y = -3x and the circle x^2 + y^2 = 3.","es":"Resolver algebraica y gráficamente un sistema sencillo formado por una ecuación lineal y una cuadrática con dos variables. Por ejemplo, hallar los puntos de intersección de la recta y = -3x y la circunferencia x^2 + y^2 = 3."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[66]}'::jsonb, '[]'::jsonb, true),
    ('HSA-REI.D.10', 'HSA-REI.D', 'A-REI.10', 'CCSS.MATH.CONTENT.HSA-REI.D.10', '{"en":"Understand that the graph of an equation in two variables is the set of all its solutions plotted in the coordinate plane, often forming a curve (which could be a line).","es":"Comprender que la gráfica de una ecuación con dos variables es el conjunto de todas sus soluciones representadas en el plano de coordenadas, que a menudo forma una curva (que puede ser una recta)."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[66]}'::jsonb, '[]'::jsonb, true),
    ('HSA-REI.D.11', 'HSA-REI.D', 'A-REI.11', 'CCSS.MATH.CONTENT.HSA-REI.D.11', '{"en":"Explain why the x-coordinates of the points where the graphs of the equations y = f(x) and y = g(x) intersect are the solutions of the equation f(x) = g(x); find the solutions approximately, e.g., using technology to graph the functions, make tables of values, or find successive approximations. Include cases where f(x) and/or g(x) are linear, polynomial, rational, absolute value, exponential, and logarithmic functions.","es":"Explicar por qué las coordenadas x de los puntos en que se cortan las gráficas de las ecuaciones y = f(x) e y = g(x) son las soluciones de f(x) = g(x); hallar las soluciones aproximadamente, por ejemplo, utilizando tecnología para representar las funciones, elaborar tablas de valores o realizar aproximaciones sucesivas. Incluir casos en que f(x) o g(x) sean funciones lineales, polinómicas, racionales, de valor absoluto, exponenciales o logarítmicas."}'::jsonb, '{"modeling":true,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[66]}'::jsonb, '[]'::jsonb, true),
    ('HSA-REI.D.12', 'HSA-REI.D', 'A-REI.12', 'CCSS.MATH.CONTENT.HSA-REI.D.12', '{"en":"Graph the solutions to a linear inequality in two variables as a half-plane (excluding the boundary in the case of a strict inequality), and graph the solution set to a system of linear inequalities in two variables as the intersection of the corresponding half-planes.","es":"Representar las soluciones de una inecuación lineal con dos variables como un semiplano (excluida la frontera en caso de desigualdad estricta) y representar el conjunto de soluciones de un sistema de inecuaciones lineales con dos variables como la intersección de los semiplanos correspondientes."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[66]}'::jsonb, '[]'::jsonb, true),
    ('8.F.A.1', '8.F.A', '8.F.1', 'CCSS.MATH.CONTENT.8.F.A.1', '{"en":"Understand that a function is a rule that assigns to each input exactly one output. The graph of a function is the set of ordered pairs consisting of an input and the corresponding output.","es":"Comprender que una función es una regla que asigna a cada entrada exactamente una salida. La gráfica de una función es el conjunto de pares ordenados formados por una entrada y su salida correspondiente."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[55]}'::jsonb, '[{"text":{"en":"Function notation is not required in Grade 8.","es":"No se exige la notación de funciones en el grado 8."},"source":{"sourceId":"ccss","pages":[55]}}]'::jsonb, true),
    ('8.F.A.2', '8.F.A', '8.F.2', 'CCSS.MATH.CONTENT.8.F.A.2', '{"en":"Compare properties of two functions each represented in a different way (algebraically, graphically, numerically in tables, or by verbal descriptions). For example, given a linear function represented by a table of values and a linear function represented by an algebraic expression, determine which function has the greater rate of change.","es":"Comparar propiedades de dos funciones representadas cada una de distinta manera (algebraicamente, gráficamente, numéricamente en tablas o mediante descripciones verbales). Por ejemplo, dadas una función lineal representada mediante una tabla de valores y otra mediante una expresión algebraica, determinar cuál tiene la mayor tasa de variación."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[55]}'::jsonb, '[]'::jsonb, true),
    ('8.F.A.3', '8.F.A', '8.F.3', 'CCSS.MATH.CONTENT.8.F.A.3', '{"en":"Interpret the equation y = mx + b as defining a linear function, whose graph is a straight line; give examples of functions that are not linear. For example, the function A = s^2 giving the area of a square as a function of its side length is not linear because its graph contains the points (1,1), (2,4) and (3,9), which are not on a straight line.","es":"Interpretar la ecuación y = mx + b como la definición de una función lineal cuya gráfica es una recta; dar ejemplos de funciones que no sean lineales. Por ejemplo, la función A = s^2 que da el área de un cuadrado en función de la longitud de su lado no es lineal porque su gráfica contiene los puntos (1,1), (2,4) y (3,9), que no están en una misma recta."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[55]}'::jsonb, '[]'::jsonb, true),
    ('8.F.B.4', '8.F.B', '8.F.4', 'CCSS.MATH.CONTENT.8.F.B.4', '{"en":"Construct a function to model a linear relationship between two quantities. Determine the rate of change and initial value of the function from a description of a relationship or from two (x, y) values, including reading these from a table or from a graph. Interpret the rate of change and initial value of a linear function in terms of the situation it models, and in terms of its graph or a table of values.","es":"Construir una función para modelar una relación lineal entre dos cantidades. Determinar la tasa de variación y el valor inicial de la función a partir de una descripción de la relación o de dos valores (x, y), incluida su lectura en una tabla o gráfica. Interpretar la tasa de variación y el valor inicial de una función lineal en términos de la situación que modela y de su gráfica o tabla de valores."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[55]}'::jsonb, '[]'::jsonb, true),
    ('8.F.B.5', '8.F.B', '8.F.5', 'CCSS.MATH.CONTENT.8.F.B.5', '{"en":"Describe qualitatively the functional relationship between two quantities by analyzing a graph (e.g., where the function is increasing or decreasing, linear or nonlinear). Sketch a graph that exhibits the qualitative features of a function that has been described verbally.","es":"Describir cualitativamente la relación funcional entre dos cantidades analizando una gráfica (por ejemplo, dónde la función es creciente o decreciente, lineal o no lineal). Esbozar una gráfica que muestre las características cualitativas de una función descrita verbalmente."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[55]}'::jsonb, '[]'::jsonb, true),
    ('HSF-IF.A.1', 'HSF-IF.A', 'F-IF.1', 'CCSS.MATH.CONTENT.HSF-IF.A.1', '{"en":"Understand that a function from one set (called the domain) to another set (called the range) assigns to each element of the domain exactly one element of the range. If f is a function and x is an element of its domain, then f(x) denotes the output of f corresponding to the input x. The graph of f is the graph of the equation y = f(x).","es":"Comprender que una función de un conjunto (llamado dominio) a otro (llamado recorrido) asigna a cada elemento del dominio exactamente un elemento del recorrido. Si f es una función y x un elemento de su dominio, f(x) denota la salida de f correspondiente a la entrada x. La gráfica de f es la gráfica de la ecuación y = f(x)."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[69]}'::jsonb, '[]'::jsonb, true),
    ('HSF-IF.A.2', 'HSF-IF.A', 'F-IF.2', 'CCSS.MATH.CONTENT.HSF-IF.A.2', '{"en":"Use function notation, evaluate functions for inputs in their domains, and interpret statements that use function notation in terms of a context.","es":"Utilizar la notación de funciones, evaluar funciones para entradas de sus dominios e interpretar afirmaciones que utilicen la notación de funciones en términos de un contexto."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[69]}'::jsonb, '[]'::jsonb, true),
    ('HSF-IF.A.3', 'HSF-IF.A', 'F-IF.3', 'CCSS.MATH.CONTENT.HSF-IF.A.3', '{"en":"Recognize that sequences are functions, sometimes defined recursively, whose domain is a subset of the integers. For example, the Fibonacci sequence is defined recursively by f(0) = f(1) = 1, f(n+1) = f(n) + f(n-1) for n ≥ 1.","es":"Reconocer que las sucesiones son funciones, a veces definidas recursivamente, cuyo dominio es un subconjunto de los números enteros. Por ejemplo, la sucesión de Fibonacci se define recursivamente mediante f(0) = f(1) = 1 y f(n+1) = f(n) + f(n-1) para n ≥ 1."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[69]}'::jsonb, '[]'::jsonb, true),
    ('HSF-IF.B.4', 'HSF-IF.B', 'F-IF.4', 'CCSS.MATH.CONTENT.HSF-IF.B.4', '{"en":"For a function that models a relationship between two quantities, interpret key features of graphs and tables in terms of the quantities, and sketch graphs showing key features given a verbal description of the relationship. Key features include: intercepts; intervals where the function is increasing, decreasing, positive, or negative; relative maximums and minimums; symmetries; end behavior; and periodicity.","es":"Para una función que modele una relación entre dos cantidades, interpretar las características principales de gráficas y tablas en términos de esas cantidades y esbozar gráficas que muestren dichas características a partir de una descripción verbal de la relación. Las características principales incluyen: intersecciones con los ejes; intervalos en que la función es creciente, decreciente, positiva o negativa; máximos y mínimos relativos; simetrías; comportamiento en los extremos del dominio; y periodicidad."}'::jsonb, '{"modeling":true,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[69]}'::jsonb, '[]'::jsonb, true),
    ('HSF-IF.B.5', 'HSF-IF.B', 'F-IF.5', 'CCSS.MATH.CONTENT.HSF-IF.B.5', '{"en":"Relate the domain of a function to its graph and, where applicable, to the quantitative relationship it describes. For example, if the function h(n) gives the number of person-hours it takes to assemble n engines in a factory, then the positive integers would be an appropriate domain for the function.","es":"Relacionar el dominio de una función con su gráfica y, cuando corresponda, con la relación cuantitativa que describe. Por ejemplo, si la función h(n) da el número de horas-persona necesarias para montar n motores en una fábrica, los enteros positivos serían un dominio adecuado para la función."}'::jsonb, '{"modeling":true,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[69]}'::jsonb, '[]'::jsonb, true),
    ('HSF-IF.B.6', 'HSF-IF.B', 'F-IF.6', 'CCSS.MATH.CONTENT.HSF-IF.B.6', '{"en":"Calculate and interpret the average rate of change of a function (presented symbolically or as a table) over a specified interval. Estimate the rate of change from a graph.","es":"Calcular e interpretar la tasa de variación media de una función (presentada simbólicamente o mediante una tabla) en un intervalo especificado. Estimar la tasa de variación a partir de una gráfica."}'::jsonb, '{"modeling":true,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[69]}'::jsonb, '[]'::jsonb, true),
    ('HSF-IF.C.7', 'HSF-IF.C', 'F-IF.7', 'CCSS.MATH.CONTENT.HSF-IF.C.7', '{"en":"Graph functions expressed symbolically and show key features of the graph, by hand in simple cases and using technology for more complicated cases.","es":"Representar gráficamente funciones expresadas simbólicamente y mostrar las características principales de la gráfica, a mano en casos sencillos y mediante tecnología en casos más complejos."}'::jsonb, '{"modeling":true,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[69]}'::jsonb, '[]'::jsonb, true),
    ('HSF-IF.C.8', 'HSF-IF.C', 'F-IF.8', 'CCSS.MATH.CONTENT.HSF-IF.C.8', '{"en":"Write a function defined by an expression in different but equivalent forms to reveal and explain different properties of the function.","es":"Escribir una función definida por una expresión en formas distintas pero equivalentes para revelar y explicar diferentes propiedades de la función."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[69]}'::jsonb, '[]'::jsonb, true),
    ('HSF-IF.C.9', 'HSF-IF.C', 'F-IF.9', 'CCSS.MATH.CONTENT.HSF-IF.C.9', '{"en":"Compare properties of two functions each represented in a different way (algebraically, graphically, numerically in tables, or by verbal descriptions). For example, given a graph of one quadratic function and an algebraic expression for another, say which has the larger maximum.","es":"Comparar propiedades de dos funciones representadas cada una de distinta manera (algebraicamente, gráficamente, numéricamente en tablas o mediante descripciones verbales). Por ejemplo, dadas la gráfica de una función cuadrática y una expresión algebraica de otra, indicar cuál tiene el mayor máximo."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[70]}'::jsonb, '[]'::jsonb, true),
    ('HSF-BF.A.1', 'HSF-BF.A', 'F-BF.1', 'CCSS.MATH.CONTENT.HSF-BF.A.1', '{"en":"Write a function that describes a relationship between two quantities.","es":"Escribir una función que describa una relación entre dos cantidades."}'::jsonb, '{"modeling":true,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[70]}'::jsonb, '[]'::jsonb, true),
    ('HSF-BF.A.2', 'HSF-BF.A', 'F-BF.2', 'CCSS.MATH.CONTENT.HSF-BF.A.2', '{"en":"Write arithmetic and geometric sequences both recursively and with an explicit formula, use them to model situations, and translate between the two forms.","es":"Escribir sucesiones aritméticas y geométricas tanto recursivamente como mediante una fórmula explícita, utilizarlas para modelar situaciones y pasar de una forma a la otra."}'::jsonb, '{"modeling":true,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[70]}'::jsonb, '[]'::jsonb, true),
    ('HSF-BF.B.3', 'HSF-BF.B', 'F-BF.3', 'CCSS.MATH.CONTENT.HSF-BF.B.3', '{"en":"Identify the effect on the graph of replacing f(x) by f(x) + k, k f(x), f(kx), and f(x + k) for specific values of k (both positive and negative); find the value of k given the graphs. Experiment with cases and illustrate an explanation of the effects on the graph using technology. Include recognizing even and odd functions from their graphs and algebraic expressions for them.","es":"Identificar el efecto sobre la gráfica de sustituir f(x) por f(x) + k, k f(x), f(kx) y f(x + k) para valores específicos de k (positivos y negativos); hallar el valor de k dadas las gráficas. Experimentar con casos e ilustrar mediante tecnología una explicación de los efectos sobre la gráfica. Incluir el reconocimiento de funciones pares e impares a partir de sus gráficas y expresiones algebraicas."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[70]}'::jsonb, '[]'::jsonb, true),
    ('HSF-BF.B.4', 'HSF-BF.B', 'F-BF.4', 'CCSS.MATH.CONTENT.HSF-BF.B.4', '{"en":"Find inverse functions.","es":"Hallar funciones inversas."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[70]}'::jsonb, '[]'::jsonb, true),
    ('HSF-LE.A.1', 'HSF-LE.A', 'F-LE.1', 'CCSS.MATH.CONTENT.HSF-LE.A.1', '{"en":"Distinguish between situations that can be modeled with linear functions and with exponential functions.","es":"Distinguir entre situaciones que pueden modelarse con funciones lineales y con funciones exponenciales."}'::jsonb, '{"modeling":true,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[70]}'::jsonb, '[]'::jsonb, true),
    ('HSF-LE.A.2', 'HSF-LE.A', 'F-LE.2', 'CCSS.MATH.CONTENT.HSF-LE.A.2', '{"en":"Construct linear and exponential functions, including arithmetic and geometric sequences, given a graph, a description of a relationship, or two input-output pairs (include reading these from a table).","es":"Construir funciones lineales y exponenciales, incluidas sucesiones aritméticas y geométricas, a partir de una gráfica, una descripción de una relación o dos pares de entrada y salida (incluida su lectura en una tabla)."}'::jsonb, '{"modeling":true,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[71]}'::jsonb, '[]'::jsonb, true),
    ('HSF-LE.A.3', 'HSF-LE.A', 'F-LE.3', 'CCSS.MATH.CONTENT.HSF-LE.A.3', '{"en":"Observe using graphs and tables that a quantity increasing exponentially eventually exceeds a quantity increasing linearly, quadratically, or (more generally) as a polynomial function.","es":"Observar mediante gráficas y tablas que una cantidad que aumenta exponencialmente acaba superando a otra que aumenta de forma lineal, cuadrática o, más generalmente, como una función polinómica."}'::jsonb, '{"modeling":true,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[71]}'::jsonb, '[]'::jsonb, true),
    ('HSF-LE.B.5', 'HSF-LE.B', 'F-LE.5', 'CCSS.MATH.CONTENT.HSF-LE.B.5', '{"en":"Interpret the parameters in a linear or exponential function in terms of a context.","es":"Interpretar los parámetros de una función lineal o exponencial en términos de un contexto."}'::jsonb, '{"modeling":true,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[71]}'::jsonb, '[]'::jsonb, true),
    ('HSF-TF.C.8', 'HSF-TF.C', 'F-TF.8', 'CCSS.MATH.CONTENT.HSF-TF.C.8', '{"en":"Prove the Pythagorean identity sin^2(θ) + cos^2(θ) = 1 and use it to find sin(θ), cos(θ), or tan(θ) given sin(θ), cos(θ), or tan(θ) and the quadrant of the angle.","es":"Demostrar la identidad pitagórica sin^2(θ) + cos^2(θ) = 1 y utilizarla para hallar sin(θ), cos(θ) o tan(θ) dados sin(θ), cos(θ) o tan(θ) y el cuadrante del ángulo."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[71]}'::jsonb, '[]'::jsonb, true),
    ('HSF-TF.C.9', 'HSF-TF.C', 'F-TF.9', 'CCSS.MATH.CONTENT.HSF-TF.C.9', '{"en":"Prove the addition and subtraction formulas for sine, cosine, and tangent and use them to solve problems.","es":"Demostrar las fórmulas de suma y diferencia del seno, coseno y tangente y utilizarlas para resolver problemas."}'::jsonb, '{"modeling":false,"plus":true}'::jsonb, '{"sourceId":"ccss","pages":[71]}'::jsonb, '[]'::jsonb, true),
    ('6.G.A.1', '6.G.A', '6.G.1', 'CCSS.MATH.CONTENT.6.G.A.1', '{"en":"Find the area of right triangles, other triangles, special quadrilaterals, and polygons by composing into rectangles or decomposing into triangles and other shapes; apply these techniques in the context of solving real-world and mathematical problems.","es":"Hallar el área de triángulos rectángulos, otros triángulos, cuadriláteros especiales y polígonos componiendo rectángulos o descomponiendo las figuras en triángulos y otras formas; aplicar estas técnicas a la resolución de problemas de la vida real y matemáticos."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[44]}'::jsonb, '[]'::jsonb, true),
    ('6.G.A.2', '6.G.A', '6.G.2', 'CCSS.MATH.CONTENT.6.G.A.2', '{"en":"Find the volume of a right rectangular prism with fractional edge lengths by packing it with unit cubes of the appropriate unit fraction edge lengths, and show that the volume is the same as would be found by multiplying the edge lengths of the prism. Apply the formulas V = l w h and V = b h to find volumes of right rectangular prisms with fractional edge lengths in the context of solving real-world and mathematical problems.","es":"Hallar el volumen de un prisma rectangular recto cuyas aristas tengan longitudes fraccionarias llenándolo con cubos unitarios de la fracción unitaria adecuada, y mostrar que el volumen coincide con el obtenido al multiplicar las longitudes de las aristas del prisma. Aplicar las fórmulas V = l w h y V = b h para hallar volúmenes de prismas rectangulares rectos con aristas de longitudes fraccionarias en problemas de la vida real y matemáticos."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[45]}'::jsonb, '[]'::jsonb, true),
    ('6.G.A.3', '6.G.A', '6.G.3', 'CCSS.MATH.CONTENT.6.G.A.3', '{"en":"Draw polygons in the coordinate plane given coordinates for the vertices; use coordinates to find the length of a side joining points with the same first coordinate or the same second coordinate. Apply these techniques in the context of solving real-world and mathematical problems.","es":"Dibujar polígonos en el plano de coordenadas dadas las coordenadas de los vértices; utilizar las coordenadas para hallar la longitud de un lado que una puntos con la misma primera coordenada o la misma segunda coordenada. Aplicar estas técnicas a la resolución de problemas de la vida real y matemáticos."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[45]}'::jsonb, '[]'::jsonb, true),
    ('6.G.A.4', '6.G.A', '6.G.4', 'CCSS.MATH.CONTENT.6.G.A.4', '{"en":"Represent three-dimensional figures using nets made up of rectangles and triangles, and use the nets to find the surface area of these figures. Apply these techniques in the context of solving real-world and mathematical problems.","es":"Representar figuras tridimensionales mediante desarrollos planos formados por rectángulos y triángulos, y utilizar estos desarrollos para hallar su área superficial. Aplicar estas técnicas a la resolución de problemas de la vida real y matemáticos."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[45]}'::jsonb, '[]'::jsonb, true),
    ('7.G.A.1', '7.G.A', '7.G.1', 'CCSS.MATH.CONTENT.7.G.A.1', '{"en":"Solve problems involving scale drawings of geometric figures, including computing actual lengths and areas from a scale drawing and reproducing a scale drawing at a different scale.","es":"Resolver problemas de dibujos a escala de figuras geométricas, incluidos el cálculo de longitudes y áreas reales a partir de un dibujo a escala y la reproducción de un dibujo a una escala diferente."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[49]}'::jsonb, '[]'::jsonb, true),
    ('7.G.A.2', '7.G.A', '7.G.2', 'CCSS.MATH.CONTENT.7.G.A.2', '{"en":"Draw (freehand, with ruler and protractor, and with technology) geometric shapes with given conditions. Focus on constructing triangles from three measures of angles or sides, noticing when the conditions determine a unique triangle, more than one triangle, or no triangle.","es":"Dibujar figuras geométricas con condiciones dadas (a mano alzada, con regla y transportador y mediante tecnología). Centrarse en la construcción de triángulos a partir de tres medidas de ángulos o lados, observando cuándo las condiciones determinan un único triángulo, más de uno o ninguno."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[50]}'::jsonb, '[]'::jsonb, true),
    ('7.G.A.3', '7.G.A', '7.G.3', 'CCSS.MATH.CONTENT.7.G.A.3', '{"en":"Describe the two-dimensional figures that result from slicing three-dimensional figures, as in plane sections of right rectangular prisms and right rectangular pyramids.","es":"Describir las figuras bidimensionales que resultan de cortar figuras tridimensionales, como en las secciones planas de prismas rectangulares rectos y pirámides rectas de base rectangular."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[50]}'::jsonb, '[]'::jsonb, true),
    ('7.G.B.4', '7.G.B', '7.G.4', 'CCSS.MATH.CONTENT.7.G.B.4', '{"en":"Know the formulas for the area and circumference of a circle and use them to solve problems; give an informal derivation of the relationship between the circumference and area of a circle.","es":"Conocer las fórmulas del área del círculo y de la longitud de la circunferencia y utilizarlas para resolver problemas; deducir de manera informal la relación entre la longitud de la circunferencia y el área del círculo."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[50]}'::jsonb, '[]'::jsonb, true)
INSERT INTO public.curriculum_standards (id, cluster_id, code, ccss_id, description, markers, source, notes, active) VALUES
    ('7.G.B.5', '7.G.B', '7.G.5', 'CCSS.MATH.CONTENT.7.G.B.5', '{"en":"Use facts about supplementary, complementary, vertical, and adjacent angles in a multi-step problem to write and solve simple equations for an unknown angle in a figure.","es":"Utilizar propiedades de ángulos suplementarios, complementarios, opuestos por el vértice y adyacentes en un problema de varios pasos para escribir y resolver ecuaciones sencillas que permitan hallar un ángulo desconocido de una figura."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[50]}'::jsonb, '[]'::jsonb, true),
    ('7.G.B.6', '7.G.B', '7.G.6', 'CCSS.MATH.CONTENT.7.G.B.6', '{"en":"Solve real-world and mathematical problems involving area, volume and surface area of two- and three-dimensional objects composed of triangles, quadrilaterals, polygons, cubes, and right prisms.","es":"Resolver problemas de la vida real y matemáticos relacionados con áreas, volúmenes y áreas superficiales de objetos bidimensionales y tridimensionales compuestos por triángulos, cuadriláteros, polígonos, cubos y prismas rectos."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[50]}'::jsonb, '[]'::jsonb, true),
    ('8.G.A.1', '8.G.A', '8.G.1', 'CCSS.MATH.CONTENT.8.G.A.1', '{"en":"Verify experimentally the properties of rotations, reflections, and translations:","es":"Verificar experimentalmente las propiedades de las rotaciones, reflexiones y traslaciones:"}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[55]}'::jsonb, '[]'::jsonb, true),
    ('8.G.A.2', '8.G.A', '8.G.2', 'CCSS.MATH.CONTENT.8.G.A.2', '{"en":"Understand that a two-dimensional figure is congruent to another if the second can be obtained from the first by a sequence of rotations, reflections, and translations; given two congruent figures, describe a sequence that exhibits the congruence between them.","es":"Comprender que una figura bidimensional es congruente con otra si la segunda puede obtenerse de la primera mediante una secuencia de rotaciones, reflexiones y traslaciones; dadas dos figuras congruentes, describir una secuencia que muestre la congruencia entre ellas."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[55]}'::jsonb, '[]'::jsonb, true),
    ('8.G.A.3', '8.G.A', '8.G.3', 'CCSS.MATH.CONTENT.8.G.A.3', '{"en":"Describe the effect of dilations, translations, rotations, and reflections on two-dimensional figures using coordinates.","es":"Describir mediante coordenadas el efecto de las homotecias, traslaciones, rotaciones y reflexiones sobre figuras bidimensionales."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[56]}'::jsonb, '[]'::jsonb, true),
    ('8.G.A.4', '8.G.A', '8.G.4', 'CCSS.MATH.CONTENT.8.G.A.4', '{"en":"Understand that a two-dimensional figure is similar to another if the second can be obtained from the first by a sequence of rotations, reflections, translations, and dilations; given two similar two-dimensional figures, describe a sequence that exhibits the similarity between them.","es":"Comprender que una figura bidimensional es semejante a otra si la segunda puede obtenerse de la primera mediante una secuencia de rotaciones, reflexiones, traslaciones y homotecias; dadas dos figuras bidimensionales semejantes, describir una secuencia que muestre la semejanza entre ellas."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[56]}'::jsonb, '[]'::jsonb, true),
    ('8.G.A.5', '8.G.A', '8.G.5', 'CCSS.MATH.CONTENT.8.G.A.5', '{"en":"Use informal arguments to establish facts about the angle sum and exterior angle of triangles, about the angles created when parallel lines are cut by a transversal, and the angle-angle criterion for similarity of triangles. For example, arrange three copies of the same triangle so that the sum of the three angles appears to form a line, and give an argument in terms of transversals why this is so.","es":"Utilizar argumentos informales para establecer propiedades de la suma de ángulos y del ángulo exterior de los triángulos, de los ángulos creados cuando una transversal corta rectas paralelas y del criterio ángulo-ángulo de semejanza de triángulos. Por ejemplo, disponer tres copias del mismo triángulo de modo que la suma de sus tres ángulos parezca formar una recta y justificar mediante transversales por qué ocurre así."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[56]}'::jsonb, '[]'::jsonb, true),
    ('8.G.B.6', '8.G.B', '8.G.6', 'CCSS.MATH.CONTENT.8.G.B.6', '{"en":"Explain a proof of the Pythagorean Theorem and its converse.","es":"Explicar una demostración del teorema de Pitágoras y de su recíproco."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[56]}'::jsonb, '[]'::jsonb, true),
    ('8.G.B.7', '8.G.B', '8.G.7', 'CCSS.MATH.CONTENT.8.G.B.7', '{"en":"Apply the Pythagorean Theorem to determine unknown side lengths in right triangles in real-world and mathematical problems in two and three dimensions.","es":"Aplicar el teorema de Pitágoras para determinar longitudes desconocidas de lados de triángulos rectángulos en problemas de la vida real y matemáticos en dos y tres dimensiones."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[56]}'::jsonb, '[]'::jsonb, true),
    ('8.G.B.8', '8.G.B', '8.G.8', 'CCSS.MATH.CONTENT.8.G.B.8', '{"en":"Apply the Pythagorean Theorem to find the distance between two points in a coordinate system.","es":"Aplicar el teorema de Pitágoras para hallar la distancia entre dos puntos en un sistema de coordenadas."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[56]}'::jsonb, '[]'::jsonb, true),
    ('8.G.C.9', '8.G.C', '8.G.9', 'CCSS.MATH.CONTENT.8.G.C.9', '{"en":"Know the formulas for the volumes of cones, cylinders, and spheres and use them to solve real-world and mathematical problems.","es":"Conocer las fórmulas de los volúmenes de conos, cilindros y esferas y utilizarlas para resolver problemas de la vida real y matemáticos."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[56]}'::jsonb, '[]'::jsonb, true),
    ('HSG-CO.A.1', 'HSG-CO.A', 'G-CO.1', 'CCSS.MATH.CONTENT.HSG-CO.A.1', '{"en":"Know precise definitions of angle, circle, perpendicular line, parallel line, and line segment, based on the undefined notions of point, line, distance along a line, and distance around a circular arc.","es":"Conocer definiciones precisas de ángulo, circunferencia, recta perpendicular, recta paralela y segmento, basadas en las nociones no definidas de punto, recta, distancia a lo largo de una recta y distancia a lo largo de un arco de circunferencia."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[76]}'::jsonb, '[]'::jsonb, true),
    ('HSG-CO.A.2', 'HSG-CO.A', 'G-CO.2', 'CCSS.MATH.CONTENT.HSG-CO.A.2', '{"en":"Represent transformations in the plane using, e.g., transparencies and geometry software; describe transformations as functions that take points in the plane as inputs and give other points as outputs. Compare transformations that preserve distance and angle to those that do not (e.g., translation versus horizontal stretch).","es":"Representar transformaciones en el plano, por ejemplo, mediante transparencias y programas de geometría; describir las transformaciones como funciones que toman puntos del plano como entradas y devuelven otros puntos como salidas. Comparar las transformaciones que conservan distancias y ángulos con las que no lo hacen (por ejemplo, una traslación frente a un estiramiento horizontal)."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[76]}'::jsonb, '[]'::jsonb, true),
    ('HSG-CO.A.3', 'HSG-CO.A', 'G-CO.3', 'CCSS.MATH.CONTENT.HSG-CO.A.3', '{"en":"Given a rectangle, parallelogram, trapezoid, or regular polygon, describe the rotations and reflections that carry it onto itself.","es":"Dado un rectángulo, paralelogramo, trapecio o polígono regular, describir las rotaciones y reflexiones que lo transforman en sí mismo."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[76]}'::jsonb, '[]'::jsonb, true),
    ('HSG-CO.A.4', 'HSG-CO.A', 'G-CO.4', 'CCSS.MATH.CONTENT.HSG-CO.A.4', '{"en":"Develop definitions of rotations, reflections, and translations in terms of angles, circles, perpendicular lines, parallel lines, and line segments.","es":"Desarrollar definiciones de rotaciones, reflexiones y traslaciones en términos de ángulos, circunferencias, rectas perpendiculares, rectas paralelas y segmentos."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[76]}'::jsonb, '[]'::jsonb, true),
    ('HSG-CO.A.5', 'HSG-CO.A', 'G-CO.5', 'CCSS.MATH.CONTENT.HSG-CO.A.5', '{"en":"Given a geometric figure and a rotation, reflection, or translation, draw the transformed figure using, e.g., graph paper, tracing paper, or geometry software. Specify a sequence of transformations that will carry a given figure onto another.","es":"Dadas una figura geométrica y una rotación, reflexión o traslación, dibujar la figura transformada utilizando, por ejemplo, papel cuadriculado, papel de calco o programas de geometría. Especificar una secuencia de transformaciones que lleve una figura dada a otra."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[76]}'::jsonb, '[]'::jsonb, true),
    ('HSG-CO.B.6', 'HSG-CO.B', 'G-CO.6', 'CCSS.MATH.CONTENT.HSG-CO.B.6', '{"en":"Use geometric descriptions of rigid motions to transform figures and to predict the effect of a given rigid motion on a given figure; given two figures, use the definition of congruence in terms of rigid motions to decide if they are congruent.","es":"Utilizar descripciones geométricas de movimientos rígidos para transformar figuras y predecir el efecto de un movimiento rígido dado sobre una figura; dadas dos figuras, utilizar la definición de congruencia en términos de movimientos rígidos para decidir si son congruentes."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[76]}'::jsonb, '[]'::jsonb, true),
    ('HSG-CO.B.7', 'HSG-CO.B', 'G-CO.7', 'CCSS.MATH.CONTENT.HSG-CO.B.7', '{"en":"Use the definition of congruence in terms of rigid motions to show that two triangles are congruent if and only if corresponding pairs of sides and corresponding pairs of angles are congruent.","es":"Utilizar la definición de congruencia en términos de movimientos rígidos para mostrar que dos triángulos son congruentes si y solo si los pares de lados correspondientes y los pares de ángulos correspondientes son congruentes."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[76]}'::jsonb, '[]'::jsonb, true),
    ('HSG-CO.B.8', 'HSG-CO.B', 'G-CO.8', 'CCSS.MATH.CONTENT.HSG-CO.B.8', '{"en":"Explain how the criteria for triangle congruence (ASA, SAS, and SSS) follow from the definition of congruence in terms of rigid motions.","es":"Explicar cómo los criterios de congruencia de triángulos (ALA, LAL y LLL; ASA, SAS y SSS en inglés) se deducen de la definición de congruencia en términos de movimientos rígidos."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[76]}'::jsonb, '[]'::jsonb, true),
    ('HSG-CO.C.9', 'HSG-CO.C', 'G-CO.9', 'CCSS.MATH.CONTENT.HSG-CO.C.9', '{"en":"Prove theorems about lines and angles. Theorems include: vertical angles are congruent; when a transversal crosses parallel lines, alternate interior angles are congruent and corresponding angles are congruent; points on a perpendicular bisector of a line segment are exactly those equidistant from the segment''s endpoints.","es":"Demostrar teoremas sobre rectas y ángulos. Entre ellos: los ángulos opuestos por el vértice son congruentes; cuando una transversal corta rectas paralelas, los ángulos alternos internos son congruentes y los correspondientes son congruentes; los puntos de la mediatriz de un segmento son exactamente los que equidistan de sus extremos."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[76]}'::jsonb, '[]'::jsonb, true),
    ('HSG-CO.C.10', 'HSG-CO.C', 'G-CO.10', 'CCSS.MATH.CONTENT.HSG-CO.C.10', '{"en":"Prove theorems about triangles. Theorems include: measures of interior angles of a triangle sum to 180°; base angles of isosceles triangles are congruent; the segment joining midpoints of two sides of a triangle is parallel to the third side and half the length; the medians of a triangle meet at a point.","es":"Demostrar teoremas sobre triángulos. Entre ellos: las medidas de los ángulos interiores de un triángulo suman 180°; los ángulos de la base de un triángulo isósceles son congruentes; el segmento que une los puntos medios de dos lados de un triángulo es paralelo al tercer lado y mide la mitad; las medianas de un triángulo se cortan en un punto."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[76]}'::jsonb, '[]'::jsonb, true),
    ('HSG-CO.C.11', 'HSG-CO.C', 'G-CO.11', 'CCSS.MATH.CONTENT.HSG-CO.C.11', '{"en":"Prove theorems about parallelograms. Theorems include: opposite sides are congruent, opposite angles are congruent, the diagonals of a parallelogram bisect each other, and conversely, rectangles are parallelograms with congruent diagonals.","es":"Demostrar teoremas sobre paralelogramos. Entre ellos: los lados opuestos son congruentes, los ángulos opuestos son congruentes, las diagonales de un paralelogramo se cortan en sus puntos medios y, recíprocamente, los rectángulos son los paralelogramos con diagonales congruentes."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[76]}'::jsonb, '[]'::jsonb, true),
    ('HSG-CO.D.12', 'HSG-CO.D', 'G-CO.12', 'CCSS.MATH.CONTENT.HSG-CO.D.12', '{"en":"Make formal geometric constructions with a variety of tools and methods (compass and straightedge, string, reflective devices, paper folding, dynamic geometric software, etc.). Copying a segment; copying an angle; bisecting a segment; bisecting an angle; constructing perpendicular lines, including the perpendicular bisector of a line segment; and constructing a line parallel to a given line through a point not on the line.","es":"Realizar construcciones geométricas formales con diversas herramientas y métodos (compás y regla sin graduar, cuerda, dispositivos reflectantes, plegado de papel, programas de geometría dinámica, etc.). Copiar un segmento; copiar un ángulo; bisecar un segmento; bisecar un ángulo; construir rectas perpendiculares, incluida la mediatriz de un segmento; y construir una recta paralela a otra dada que pase por un punto exterior a esta."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[76]}'::jsonb, '[]'::jsonb, true),
    ('HSG-CO.D.13', 'HSG-CO.D', 'G-CO.13', 'CCSS.MATH.CONTENT.HSG-CO.D.13', '{"en":"Construct an equilateral triangle, a square, and a regular hexagon inscribed in a circle.","es":"Construir un triángulo equilátero, un cuadrado y un hexágono regular inscritos en una circunferencia."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[76]}'::jsonb, '[]'::jsonb, true),
    ('HSG-SRT.A.1', 'HSG-SRT.A', 'G-SRT.1', 'CCSS.MATH.CONTENT.HSG-SRT.A.1', '{"en":"Verify experimentally the properties of dilations given by a center and a scale factor:","es":"Verificar experimentalmente las propiedades de las homotecias dadas por un centro y un factor de escala:"}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[77]}'::jsonb, '[]'::jsonb, true),
    ('HSG-SRT.A.2', 'HSG-SRT.A', 'G-SRT.2', 'CCSS.MATH.CONTENT.HSG-SRT.A.2', '{"en":"Given two figures, use the definition of similarity in terms of similarity transformations to decide if they are similar; explain using similarity transformations the meaning of similarity for triangles as the equality of all corresponding pairs of angles and the proportionality of all corresponding pairs of sides.","es":"Dadas dos figuras, utilizar la definición de semejanza en términos de transformaciones de semejanza para decidir si son semejantes; explicar mediante esas transformaciones que la semejanza de triángulos implica la igualdad de todos los pares de ángulos correspondientes y la proporcionalidad de todos los pares de lados correspondientes."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[77]}'::jsonb, '[]'::jsonb, true),
    ('HSG-SRT.A.3', 'HSG-SRT.A', 'G-SRT.3', 'CCSS.MATH.CONTENT.HSG-SRT.A.3', '{"en":"Use the properties of similarity transformations to establish the AA criterion for two triangles to be similar.","es":"Utilizar las propiedades de las transformaciones de semejanza para establecer el criterio AA de semejanza de dos triángulos."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[77]}'::jsonb, '[]'::jsonb, true),
    ('HSG-SRT.B.4', 'HSG-SRT.B', 'G-SRT.4', 'CCSS.MATH.CONTENT.HSG-SRT.B.4', '{"en":"Prove theorems about triangles. Theorems include: a line parallel to one side of a triangle divides the other two proportionally, and conversely; the Pythagorean Theorem proved using triangle similarity.","es":"Demostrar teoremas sobre triángulos. Entre ellos: una recta paralela a un lado de un triángulo divide los otros dos proporcionalmente, y recíprocamente; el teorema de Pitágoras demostrado mediante semejanza de triángulos."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[77]}'::jsonb, '[]'::jsonb, true),
    ('HSG-SRT.B.5', 'HSG-SRT.B', 'G-SRT.5', 'CCSS.MATH.CONTENT.HSG-SRT.B.5', '{"en":"Use congruence and similarity criteria for triangles to solve problems and to prove relationships in geometric figures.","es":"Utilizar criterios de congruencia y semejanza de triángulos para resolver problemas y demostrar relaciones en figuras geométricas."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[77]}'::jsonb, '[]'::jsonb, true),
    ('HSG-SRT.C.6', 'HSG-SRT.C', 'G-SRT.6', 'CCSS.MATH.CONTENT.HSG-SRT.C.6', '{"en":"Understand that by similarity, side ratios in right triangles are properties of the angles in the triangle, leading to definitions of trigonometric ratios for acute angles.","es":"Comprender que, por semejanza, las razones entre lados de triángulos rectángulos son propiedades de sus ángulos, lo que conduce a las definiciones de razones trigonométricas de ángulos agudos."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[77]}'::jsonb, '[]'::jsonb, true),
    ('HSG-SRT.C.7', 'HSG-SRT.C', 'G-SRT.7', 'CCSS.MATH.CONTENT.HSG-SRT.C.7', '{"en":"Explain and use the relationship between the sine and cosine of complementary angles.","es":"Explicar y utilizar la relación entre el seno y el coseno de ángulos complementarios."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[77]}'::jsonb, '[]'::jsonb, true),
    ('HSG-SRT.C.8', 'HSG-SRT.C', 'G-SRT.8', 'CCSS.MATH.CONTENT.HSG-SRT.C.8', '{"en":"Use trigonometric ratios and the Pythagorean Theorem to solve right triangles in applied problems.","es":"Utilizar las razones trigonométricas y el teorema de Pitágoras para resolver triángulos rectángulos en problemas aplicados."}'::jsonb, '{"modeling":true,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[77]}'::jsonb, '[]'::jsonb, true),
    ('HSG-C.A.1', 'HSG-C.A', 'G-C.1', 'CCSS.MATH.CONTENT.HSG-C.A.1', '{"en":"Prove that all circles are similar.","es":"Demostrar que todas las circunferencias son semejantes."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[77]}'::jsonb, '[]'::jsonb, true),
    ('HSG-C.A.2', 'HSG-C.A', 'G-C.2', 'CCSS.MATH.CONTENT.HSG-C.A.2', '{"en":"Identify and describe relationships among inscribed angles, radii, and chords. Include the relationship between central, inscribed, and circumscribed angles; inscribed angles on a diameter are right angles; the radius of a circle is perpendicular to the tangent where the radius intersects the circle.","es":"Identificar y describir relaciones entre ángulos inscritos, radios y cuerdas. Incluir la relación entre ángulos centrales, inscritos y circunscritos; que los ángulos inscritos que abarcan un diámetro son rectos; y que el radio de una circunferencia es perpendicular a la tangente en el punto de tangencia."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[77]}'::jsonb, '[]'::jsonb, true),
    ('HSG-C.A.3', 'HSG-C.A', 'G-C.3', 'CCSS.MATH.CONTENT.HSG-C.A.3', '{"en":"Construct the inscribed and circumscribed circles of a triangle, and prove properties of angles for a quadrilateral inscribed in a circle.","es":"Construir las circunferencias inscrita y circunscrita de un triángulo y demostrar propiedades de los ángulos de un cuadrilátero inscrito en una circunferencia."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[77]}'::jsonb, '[]'::jsonb, true),
    ('HSG-C.A.4', 'HSG-C.A', 'G-C.4', 'CCSS.MATH.CONTENT.HSG-C.A.4', '{"en":"Construct a tangent line from a point outside a given circle to the circle.","es":"Construir una recta tangente a una circunferencia dada desde un punto exterior a ella."}'::jsonb, '{"modeling":false,"plus":true}'::jsonb, '{"sourceId":"ccss","pages":[77]}'::jsonb, '[]'::jsonb, true),
    ('HSG-C.B.5', 'HSG-C.B', 'G-C.5', 'CCSS.MATH.CONTENT.HSG-C.B.5', '{"en":"Derive using similarity the fact that the length of the arc intercepted by an angle is proportional to the radius, and define the radian measure of the angle as the constant of proportionality; derive the formula for the area of a sector.","es":"Deducir mediante semejanza que la longitud del arco abarcado por un ángulo es proporcional al radio y definir la medida del ángulo en radianes como la constante de proporcionalidad; deducir la fórmula del área de un sector circular."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[78]}'::jsonb, '[]'::jsonb, true),
    ('HSG-GPE.A.1', 'HSG-GPE.A', 'G-GPE.1', 'CCSS.MATH.CONTENT.HSG-GPE.A.1', '{"en":"Derive the equation of a circle of given center and radius using the Pythagorean Theorem; complete the square to find the center and radius of a circle given by an equation.","es":"Deducir la ecuación de una circunferencia de centro y radio dados mediante el teorema de Pitágoras; completar el cuadrado para hallar el centro y el radio de una circunferencia dada por una ecuación."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[78]}'::jsonb, '[]'::jsonb, true),
    ('HSG-GPE.A.2', 'HSG-GPE.A', 'G-GPE.2', 'CCSS.MATH.CONTENT.HSG-GPE.A.2', '{"en":"Derive the equation of a parabola given a focus and directrix.","es":"Deducir la ecuación de una parábola dados un foco y una directriz."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[78]}'::jsonb, '[]'::jsonb, true),
    ('HSG-GPE.B.4', 'HSG-GPE.B', 'G-GPE.4', 'CCSS.MATH.CONTENT.HSG-GPE.B.4', '{"en":"Use coordinates to prove simple geometric theorems algebraically. For example, prove or disprove that a figure defined by four given points in the coordinate plane is a rectangle; prove or disprove that the point (1, √3) lies on the circle centered at the origin and containing the point (0, 2).","es":"Utilizar coordenadas para demostrar algebraicamente teoremas geométricos sencillos. Por ejemplo, demostrar o refutar que una figura definida por cuatro puntos dados del plano de coordenadas es un rectángulo; demostrar o refutar que el punto (1, √3) pertenece a la circunferencia centrada en el origen que pasa por el punto (0, 2)."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[78]}'::jsonb, '[]'::jsonb, true),
    ('HSG-GPE.B.5', 'HSG-GPE.B', 'G-GPE.5', 'CCSS.MATH.CONTENT.HSG-GPE.B.5', '{"en":"Prove the slope criteria for parallel and perpendicular lines and use them to solve geometric problems (e.g., find the equation of a line parallel or perpendicular to a given line that passes through a given point).","es":"Demostrar los criterios de pendientes de rectas paralelas y perpendiculares y utilizarlos para resolver problemas geométricos (por ejemplo, hallar la ecuación de una recta paralela o perpendicular a otra dada que pase por un punto dado)."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[78]}'::jsonb, '[]'::jsonb, true),
    ('HSG-GPE.B.6', 'HSG-GPE.B', 'G-GPE.6', 'CCSS.MATH.CONTENT.HSG-GPE.B.6', '{"en":"Find the point on a directed line segment between two given points that partitions the segment in a given ratio.","es":"Hallar el punto de un segmento dirigido entre dos puntos dados que divide el segmento en una razón dada."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[78]}'::jsonb, '[]'::jsonb, true),
    ('HSG-GPE.B.7', 'HSG-GPE.B', 'G-GPE.7', 'CCSS.MATH.CONTENT.HSG-GPE.B.7', '{"en":"Use coordinates to compute perimeters of polygons and areas of triangles and rectangles, e.g., using the distance formula.","es":"Utilizar coordenadas para calcular perímetros de polígonos y áreas de triángulos y rectángulos, por ejemplo, mediante la fórmula de la distancia."}'::jsonb, '{"modeling":true,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[78]}'::jsonb, '[]'::jsonb, true),
    ('HSG-GMD.A.1', 'HSG-GMD.A', 'G-GMD.1', 'CCSS.MATH.CONTENT.HSG-GMD.A.1', '{"en":"Give an informal argument for the formulas for the circumference of a circle, area of a circle, volume of a cylinder, pyramid, and cone. Use dissection arguments, Cavalieri''s principle, and informal limit arguments.","es":"Dar un argumento informal para las fórmulas de la longitud de una circunferencia, el área de un círculo y el volumen de un cilindro, una pirámide y un cono. Utilizar argumentos de descomposición, el principio de Cavalieri y argumentos informales de límites."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[78]}'::jsonb, '[]'::jsonb, true),
    ('HSG-GMD.A.3', 'HSG-GMD.A', 'G-GMD.3', 'CCSS.MATH.CONTENT.HSG-GMD.A.3', '{"en":"Use volume formulas for cylinders, pyramids, cones, and spheres to solve problems.","es":"Utilizar las fórmulas del volumen de cilindros, pirámides, conos y esferas para resolver problemas."}'::jsonb, '{"modeling":true,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[78]}'::jsonb, '[]'::jsonb, true),
    ('6.SP.A.1', '6.SP.A', '6.SP.1', 'CCSS.MATH.CONTENT.6.SP.A.1', '{"en":"Recognize a statistical question as one that anticipates variability in the data related to the question and accounts for it in the answers. For example, \"How old am I?\" is not a statistical question, but \"How old are the students in my school?\" is a statistical question because one anticipates variability in students'' ages.","es":"Reconocer una pregunta estadística como aquella que anticipa variabilidad en los datos relacionados con la pregunta y la tiene en cuenta en las respuestas. Por ejemplo, «¿Cuántos años tengo?» no es una pregunta estadística, pero «¿Cuántos años tienen los estudiantes de mi colegio?» sí lo es, porque se anticipa variabilidad en las edades de los estudiantes."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[45]}'::jsonb, '[]'::jsonb, true),
    ('6.SP.A.2', '6.SP.A', '6.SP.2', 'CCSS.MATH.CONTENT.6.SP.A.2', '{"en":"Understand that a set of data collected to answer a statistical question has a distribution which can be described by its center, spread, and overall shape.","es":"Comprender que un conjunto de datos recogidos para responder a una pregunta estadística tiene una distribución que puede describirse por su centro, dispersión y forma general."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[45]}'::jsonb, '[]'::jsonb, true),
    ('6.SP.A.3', '6.SP.A', '6.SP.3', 'CCSS.MATH.CONTENT.6.SP.A.3', '{"en":"Recognize that a measure of center for a numerical data set summarizes all of its values with a single number, while a measure of variation describes how its values vary with a single number.","es":"Reconocer que una medida de centralización de un conjunto de datos numéricos resume todos sus valores con un único número, mientras que una medida de variación describe con un único número cómo varían sus valores."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[45]}'::jsonb, '[]'::jsonb, true),
    ('6.SP.B.4', '6.SP.B', '6.SP.4', 'CCSS.MATH.CONTENT.6.SP.B.4', '{"en":"Display numerical data in plots on a number line, including dot plots, histograms, and box plots.","es":"Representar datos numéricos mediante gráficos sobre una recta numérica, incluidos diagramas de puntos, histogramas y diagramas de caja."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[45]}'::jsonb, '[]'::jsonb, true),
    ('6.SP.B.5', '6.SP.B', '6.SP.5', 'CCSS.MATH.CONTENT.6.SP.B.5', '{"en":"Summarize numerical data sets in relation to their context, such as by:","es":"Resumir conjuntos de datos numéricos en relación con su contexto, por ejemplo, mediante:"}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[45]}'::jsonb, '[]'::jsonb, true),
    ('7.SP.A.1', '7.SP.A', '7.SP.1', 'CCSS.MATH.CONTENT.7.SP.A.1', '{"en":"Understand that statistics can be used to gain information about a population by examining a sample of the population; generalizations about a population from a sample are valid only if the sample is representative of that population. Understand that random sampling tends to produce representative samples and support valid inferences.","es":"Comprender que la estadística permite obtener información sobre una población examinando una muestra de ella; las generalizaciones sobre una población a partir de una muestra solo son válidas si la muestra es representativa de esa población. Comprender que el muestreo aleatorio tiende a producir muestras representativas y a sustentar inferencias válidas."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[50]}'::jsonb, '[]'::jsonb, true),
    ('7.SP.A.2', '7.SP.A', '7.SP.2', 'CCSS.MATH.CONTENT.7.SP.A.2', '{"en":"Use data from a random sample to draw inferences about a population with an unknown characteristic of interest. Generate multiple samples (or simulated samples) of the same size to gauge the variation in estimates or predictions. For example, estimate the mean word length in a book by randomly sampling words from the book; predict the winner of a school election based on randomly sampled survey data. Gauge how far off the estimate or prediction might be.","es":"Utilizar datos de una muestra aleatoria para extraer inferencias sobre una población con una característica de interés desconocida. Generar varias muestras (o muestras simuladas) del mismo tamaño para valorar la variación de las estimaciones o predicciones. Por ejemplo, estimar la longitud media de las palabras de un libro mediante un muestreo aleatorio de sus palabras; predecir el ganador de una elección escolar a partir de datos de encuestas con muestreo aleatorio. Valorar cuánto podría desviarse la estimación o predicción."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[50]}'::jsonb, '[]'::jsonb, true),
    ('7.SP.B.3', '7.SP.B', '7.SP.3', 'CCSS.MATH.CONTENT.7.SP.B.3', '{"en":"Informally assess the degree of visual overlap of two numerical data distributions with similar variabilities, measuring the difference between the centers by expressing it as a multiple of a measure of variability. For example, the mean height of players on the basketball team is 10 cm greater than the mean height of players on the soccer team, about twice the variability (mean absolute deviation) on either team; on a dot plot, the separation between the two distributions of heights is noticeable.","es":"Evaluar informalmente el grado de solapamiento visual de dos distribuciones de datos numéricos con variabilidades similares, midiendo la diferencia entre sus centros como múltiplo de una medida de variabilidad. Por ejemplo, la estatura media de los jugadores del equipo de baloncesto es 10 cm mayor que la del equipo de fútbol, aproximadamente el doble de la variabilidad (desviación absoluta media) de cualquiera de los dos equipos; en un diagrama de puntos se aprecia la separación entre las dos distribuciones de estaturas."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[50]}'::jsonb, '[]'::jsonb, true),
    ('7.SP.B.4', '7.SP.B', '7.SP.4', 'CCSS.MATH.CONTENT.7.SP.B.4', '{"en":"Use measures of center and measures of variability for numerical data from random samples to draw informal comparative inferences about two populations. For example, decide whether the words in a chapter of a seventh-grade science book are generally longer than the words in a chapter of a fourth-grade science book.","es":"Utilizar medidas de centralización y variabilidad de datos numéricos de muestras aleatorias para extraer inferencias comparativas informales sobre dos poblaciones. Por ejemplo, decidir si las palabras de un capítulo de un libro de ciencias de séptimo grado son, en general, más largas que las de un capítulo de un libro de ciencias de cuarto grado."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[50]}'::jsonb, '[]'::jsonb, true),
    ('7.SP.C.5', '7.SP.C', '7.SP.5', 'CCSS.MATH.CONTENT.7.SP.C.5', '{"en":"Understand that the probability of a chance event is a number between 0 and 1 that expresses the likelihood of the event occurring. Larger numbers indicate greater likelihood. A probability near 0 indicates an unlikely event, a probability around 1/2 indicates an event that is neither unlikely nor likely, and a probability near 1 indicates a likely event.","es":"Comprender que la probabilidad de un suceso aleatorio es un número entre 0 y 1 que expresa la posibilidad de que ocurra. Los números mayores indican una mayor posibilidad. Una probabilidad cercana a 0 indica un suceso poco probable; una probabilidad cercana a 1/2 indica un suceso tan probable como improbable; y una probabilidad cercana a 1 indica un suceso probable."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[50]}'::jsonb, '[]'::jsonb, true),
    ('7.SP.C.6', '7.SP.C', '7.SP.6', 'CCSS.MATH.CONTENT.7.SP.C.6', '{"en":"Approximate the probability of a chance event by collecting data on the chance process that produces it and observing its long-run relative frequency, and predict the approximate relative frequency given the probability. For example, when rolling a number cube 600 times, predict that a 3 or 6 would be rolled roughly 200 times, but probably not exactly 200 times.","es":"Aproximar la probabilidad de un suceso aleatorio recogiendo datos del proceso aleatorio que lo produce y observando su frecuencia relativa a largo plazo, y predecir la frecuencia relativa aproximada dada la probabilidad. Por ejemplo, al lanzar un dado 600 veces, predecir que saldrá un 3 o un 6 unas 200 veces, aunque probablemente no exactamente 200."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[51]}'::jsonb, '[]'::jsonb, true),
    ('7.SP.C.7', '7.SP.C', '7.SP.7', 'CCSS.MATH.CONTENT.7.SP.C.7', '{"en":"Develop a probability model and use it to find probabilities of events. Compare probabilities from a model to observed frequencies; if the agreement is not good, explain possible sources of the discrepancy.","es":"Desarrollar un modelo de probabilidad y utilizarlo para hallar probabilidades de sucesos. Comparar las probabilidades del modelo con las frecuencias observadas; si no concuerdan bien, explicar las posibles causas de la discrepancia."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[51]}'::jsonb, '[]'::jsonb, true),
    ('7.SP.C.8', '7.SP.C', '7.SP.8', 'CCSS.MATH.CONTENT.7.SP.C.8', '{"en":"Find probabilities of compound events using organized lists, tables, tree diagrams, and simulation.","es":"Hallar probabilidades de sucesos compuestos mediante listas organizadas, tablas, diagramas de árbol y simulaciones."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[51]}'::jsonb, '[]'::jsonb, true),
    ('8.SP.A.1', '8.SP.A', '8.SP.1', 'CCSS.MATH.CONTENT.8.SP.A.1', '{"en":"Construct and interpret scatter plots for bivariate measurement data to investigate patterns of association between two quantities. Describe patterns such as clustering, outliers, positive or negative association, linear association, and nonlinear association.","es":"Construir e interpretar diagramas de dispersión de datos de medición bivariantes para investigar patrones de asociación entre dos cantidades. Describir patrones como agrupaciones, valores atípicos, asociación positiva o negativa, asociación lineal y asociación no lineal."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[56]}'::jsonb, '[]'::jsonb, true),
    ('8.SP.A.2', '8.SP.A', '8.SP.2', 'CCSS.MATH.CONTENT.8.SP.A.2', '{"en":"Know that straight lines are widely used to model relationships between two quantitative variables. For scatter plots that suggest a linear association, informally fit a straight line, and informally assess the model fit by judging the closeness of the data points to the line.","es":"Saber que las rectas se utilizan ampliamente para modelar relaciones entre dos variables cuantitativas. En diagramas de dispersión que sugieran una asociación lineal, ajustar informalmente una recta y evaluar de manera informal el ajuste del modelo según la proximidad de los puntos de datos a la recta."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[56]}'::jsonb, '[]'::jsonb, true),
    ('8.SP.A.3', '8.SP.A', '8.SP.3', 'CCSS.MATH.CONTENT.8.SP.A.3', '{"en":"Use the equation of a linear model to solve problems in the context of bivariate measurement data, interpreting the slope and intercept. For example, in a linear model for a biology experiment, interpret a slope of 1.5 cm/hr as meaning that an additional hour of sunlight each day is associated with an additional 1.5 cm in mature plant height.","es":"Utilizar la ecuación de un modelo lineal para resolver problemas en el contexto de datos de medición bivariantes, interpretando la pendiente y la ordenada en el origen. Por ejemplo, en un modelo lineal de un experimento de biología, interpretar una pendiente de 1.5 cm/h como que una hora adicional de luz solar diaria se asocia con 1.5 cm adicionales de altura de la planta adulta."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[56]}'::jsonb, '[]'::jsonb, true),
    ('8.SP.A.4', '8.SP.A', '8.SP.4', 'CCSS.MATH.CONTENT.8.SP.A.4', '{"en":"Understand that patterns of association can also be seen in bivariate categorical data by displaying frequencies and relative frequencies in a two-way table. Construct and interpret a two-way table summarizing data on two categorical variables collected from the same subjects. Use relative frequencies calculated for rows or columns to describe possible association between the two variables. For example, collect data from students in your class on whether or not they have a curfew on school nights and whether or not they have assigned chores at home. Is there evidence that those who have a curfew also tend to have chores?","es":"Comprender que también pueden observarse patrones de asociación en datos categóricos bivariantes representando frecuencias y frecuencias relativas en una tabla de doble entrada. Construir e interpretar una tabla de doble entrada que resuma datos de dos variables categóricas recogidos de los mismos sujetos. Utilizar frecuencias relativas calculadas por filas o columnas para describir una posible asociación entre ambas variables. Por ejemplo, recoger datos de los estudiantes de la clase sobre si tienen una hora límite para volver a casa las noches previas a días lectivos y si tienen tareas domésticas asignadas. ¿Hay indicios de que quienes tienen una hora límite también tienden a tener tareas domésticas?"}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[56]}'::jsonb, '[]'::jsonb, true),
    ('HSS-ID.A.1', 'HSS-ID.A', 'S-ID.1', 'CCSS.MATH.CONTENT.HSS-ID.A.1', '{"en":"Represent data with plots on the real number line (dot plots, histograms, and box plots).","es":"Representar datos mediante gráficos sobre la recta real (diagramas de puntos, histogramas y diagramas de caja)."}'::jsonb, '{"modeling":true,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[81]}'::jsonb, '[]'::jsonb, true),
    ('HSS-ID.A.2', 'HSS-ID.A', 'S-ID.2', 'CCSS.MATH.CONTENT.HSS-ID.A.2', '{"en":"Use statistics appropriate to the shape of the data distribution to compare center (median, mean) and spread (interquartile range, standard deviation) of two or more different data sets.","es":"Utilizar estadísticos adecuados a la forma de la distribución para comparar el centro (mediana, media) y la dispersión (rango intercuartílico, desviación típica) de dos o más conjuntos de datos distintos."}'::jsonb, '{"modeling":true,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[81]}'::jsonb, '[]'::jsonb, true),
    ('HSS-ID.A.3', 'HSS-ID.A', 'S-ID.3', 'CCSS.MATH.CONTENT.HSS-ID.A.3', '{"en":"Interpret differences in shape, center, and spread in the context of the data sets, accounting for possible effects of extreme data points (outliers).","es":"Interpretar diferencias de forma, centro y dispersión en el contexto de los conjuntos de datos, teniendo en cuenta los posibles efectos de los valores extremos (valores atípicos)."}'::jsonb, '{"modeling":true,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[81]}'::jsonb, '[]'::jsonb, true),
    ('HSS-ID.B.5', 'HSS-ID.B', 'S-ID.5', 'CCSS.MATH.CONTENT.HSS-ID.B.5', '{"en":"Summarize categorical data for two categories in two-way frequency tables. Interpret relative frequencies in the context of the data (including joint, marginal, and conditional relative frequencies). Recognize possible associations and trends in the data.","es":"Resumir datos categóricos de dos categorías en tablas de frecuencias de doble entrada. Interpretar las frecuencias relativas en el contexto de los datos (incluidas las frecuencias relativas conjuntas, marginales y condicionadas). Reconocer posibles asociaciones y tendencias en los datos."}'::jsonb, '{"modeling":true,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[81]}'::jsonb, '[]'::jsonb, true),
    ('HSS-ID.B.6', 'HSS-ID.B', 'S-ID.6', 'CCSS.MATH.CONTENT.HSS-ID.B.6', '{"en":"Represent data on two quantitative variables on a scatter plot, and describe how the variables are related.","es":"Representar datos de dos variables cuantitativas en un diagrama de dispersión y describir cómo se relacionan las variables."}'::jsonb, '{"modeling":true,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[81]}'::jsonb, '[]'::jsonb, true),
    ('HSS-ID.C.7', 'HSS-ID.C', 'S-ID.7', 'CCSS.MATH.CONTENT.HSS-ID.C.7', '{"en":"Interpret the slope (rate of change) and the intercept (constant term) of a linear model in the context of the data.","es":"Interpretar la pendiente (tasa de variación) y la ordenada en el origen (término constante) de un modelo lineal en el contexto de los datos."}'::jsonb, '{"modeling":true,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[81]}'::jsonb, '[]'::jsonb, true),
    ('HSS-ID.C.8', 'HSS-ID.C', 'S-ID.8', 'CCSS.MATH.CONTENT.HSS-ID.C.8', '{"en":"Compute (using technology) and interpret the correlation coefficient of a linear fit.","es":"Calcular mediante tecnología e interpretar el coeficiente de correlación de un ajuste lineal."}'::jsonb, '{"modeling":true,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[81]}'::jsonb, '[]'::jsonb, true),
    ('HSS-ID.C.9', 'HSS-ID.C', 'S-ID.9', 'CCSS.MATH.CONTENT.HSS-ID.C.9', '{"en":"Distinguish between correlation and causation.","es":"Distinguir entre correlación y causalidad."}'::jsonb, '{"modeling":true,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[81]}'::jsonb, '[]'::jsonb, true),
    ('HSS-CP.A.1', 'HSS-CP.A', 'S-CP.1', 'CCSS.MATH.CONTENT.HSS-CP.A.1', '{"en":"Describe events as subsets of a sample space (the set of outcomes) using characteristics (or categories) of the outcomes, or as unions, intersections, or complements of other events (\"or,\" \"and,\" \"not\").","es":"Describir sucesos como subconjuntos de un espacio muestral (el conjunto de resultados), utilizando características o categorías de los resultados, o como uniones, intersecciones o complementarios de otros sucesos («o», «y», «no»)."}'::jsonb, '{"modeling":true,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[82]}'::jsonb, '[]'::jsonb, true),
    ('HSS-CP.A.2', 'HSS-CP.A', 'S-CP.2', 'CCSS.MATH.CONTENT.HSS-CP.A.2', '{"en":"Understand that two events A and B are independent if the probability of A and B occurring together is the product of their probabilities, and use this characterization to determine if they are independent.","es":"Comprender que dos sucesos A y B son independientes si la probabilidad de que ocurran conjuntamente es el producto de sus probabilidades y utilizar esta caracterización para determinar si son independientes."}'::jsonb, '{"modeling":true,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[82]}'::jsonb, '[]'::jsonb, true),
    ('HSS-CP.A.3', 'HSS-CP.A', 'S-CP.3', 'CCSS.MATH.CONTENT.HSS-CP.A.3', '{"en":"Understand the conditional probability of A given B as P(A and B)/P(B), and interpret independence of A and B as saying that the conditional probability of A given B is the same as the probability of A, and the conditional probability of B given A is the same as the probability of B.","es":"Comprender la probabilidad condicionada de A dado B como P(A y B)/P(B), e interpretar la independencia de A y B como que la probabilidad condicionada de A dado B es igual a la probabilidad de A y que la probabilidad condicionada de B dado A es igual a la probabilidad de B."}'::jsonb, '{"modeling":true,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[82]}'::jsonb, '[]'::jsonb, true),
    ('HSS-CP.A.4', 'HSS-CP.A', 'S-CP.4', 'CCSS.MATH.CONTENT.HSS-CP.A.4', '{"en":"Construct and interpret two-way frequency tables of data when two categories are associated with each object being classified. Use the two-way table as a sample space to decide if events are independent and to approximate conditional probabilities. For example, collect data from a random sample of students in your school on their favorite subject among math, science, and English. Estimate the probability that a randomly selected student from your school will favor science given that the student is in tenth grade. Do the same for other subjects and compare the results.","es":"Construir e interpretar tablas de frecuencias de doble entrada cuando cada objeto clasificado tiene asociadas dos categorías. Utilizar la tabla como espacio muestral para decidir si los sucesos son independientes y aproximar probabilidades condicionadas. Por ejemplo, recoger datos de una muestra aleatoria de estudiantes del centro sobre su asignatura preferida entre matemáticas, ciencias e inglés. Estimar la probabilidad de que un estudiante seleccionado al azar prefiera ciencias dado que cursa décimo grado. Hacer lo mismo para otras asignaturas y comparar los resultados."}'::jsonb, '{"modeling":true,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[82]}'::jsonb, '[]'::jsonb, true),
    ('HSS-CP.A.5', 'HSS-CP.A', 'S-CP.5', 'CCSS.MATH.CONTENT.HSS-CP.A.5', '{"en":"Recognize and explain the concepts of conditional probability and independence in everyday language and everyday situations. For example, compare the chance of having lung cancer if you are a smoker with the chance of being a smoker if you have lung cancer.","es":"Reconocer y explicar los conceptos de probabilidad condicionada e independencia en lenguaje y situaciones cotidianos. Por ejemplo, comparar la probabilidad de tener cáncer de pulmón si se es fumador con la probabilidad de ser fumador si se tiene cáncer de pulmón."}'::jsonb, '{"modeling":true,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[82]}'::jsonb, '[]'::jsonb, true),
    ('HSS-CP.B.6', 'HSS-CP.B', 'S-CP.6', 'CCSS.MATH.CONTENT.HSS-CP.B.6', '{"en":"Find the conditional probability of A given B as the fraction of B''s outcomes that also belong to A, and interpret the answer in terms of the model.","es":"Hallar la probabilidad condicionada de A dado B como la fracción de resultados de B que también pertenecen a A e interpretar la respuesta en términos del modelo."}'::jsonb, '{"modeling":true,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[82]}'::jsonb, '[]'::jsonb, true),
    ('HSS-CP.B.7', 'HSS-CP.B', 'S-CP.7', 'CCSS.MATH.CONTENT.HSS-CP.B.7', '{"en":"Apply the Addition Rule, P(A or B) = P(A) + P(B) - P(A and B), and interpret the answer in terms of the model.","es":"Aplicar la regla de la suma, P(A o B) = P(A) + P(B) - P(A y B), e interpretar la respuesta en términos del modelo."}'::jsonb, '{"modeling":true,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[82]}'::jsonb, '[]'::jsonb, true),
    ('HSS-CP.B.8', 'HSS-CP.B', 'S-CP.8', 'CCSS.MATH.CONTENT.HSS-CP.B.8', '{"en":"Apply the general Multiplication Rule in a uniform probability model, P(A and B) = P(A)P(B|A) = P(B)P(A|B), and interpret the answer in terms of the model.","es":"Aplicar la regla general de la multiplicación en un modelo de probabilidad uniforme, P(A y B) = P(A)P(B|A) = P(B)P(A|B), e interpretar la respuesta en términos del modelo."}'::jsonb, '{"modeling":true,"plus":true}'::jsonb, '{"sourceId":"ccss","pages":[82]}'::jsonb, '[]'::jsonb, true),
    ('HSS-CP.B.9', 'HSS-CP.B', 'S-CP.9', 'CCSS.MATH.CONTENT.HSS-CP.B.9', '{"en":"Use permutations and combinations to compute probabilities of compound events and solve problems.","es":"Utilizar permutaciones y combinaciones para calcular probabilidades de sucesos compuestos y resolver problemas."}'::jsonb, '{"modeling":true,"plus":true}'::jsonb, '{"sourceId":"ccss","pages":[82]}'::jsonb, '[]'::jsonb, true),
    ('HSS-MD.B.6', 'HSS-MD.B', 'S-MD.6', 'CCSS.MATH.CONTENT.HSS-MD.B.6', '{"en":"Use probabilities to make fair decisions (e.g., drawing by lots, using a random number generator).","es":"Utilizar probabilidades para tomar decisiones justas (por ejemplo, mediante sorteos o utilizando un generador de números aleatorios)."}'::jsonb, '{"modeling":true,"plus":true}'::jsonb, '{"sourceId":"ccss","pages":[83]}'::jsonb, '[]'::jsonb, true),
    ('HSS-MD.B.7', 'HSS-MD.B', 'S-MD.7', 'CCSS.MATH.CONTENT.HSS-MD.B.7', '{"en":"Analyze decisions and strategies using probability concepts (e.g., product testing, medical testing, pulling a hockey goalie at the end of a game).","es":"Analizar decisiones y estrategias mediante conceptos de probabilidad (por ejemplo, pruebas de productos, pruebas médicas o retirar al portero de hockey al final de un partido)."}'::jsonb, '{"modeling":true,"plus":true}'::jsonb, '{"sourceId":"ccss","pages":[83]}'::jsonb, '[]'::jsonb, true)
INSERT INTO public.curriculum_substandards (id, standard_id, code, ccss_id, description, markers, source, active) VALUES
    ('6.NS.C.6a', '6.NS.C.6', '6.NS.6.a', 'CCSS.MATH.CONTENT.6.NS.C.6a', '{"en":"Recognize opposite signs of numbers as indicating locations on opposite sides of 0 on the number line; recognize that the opposite of the opposite of a number is the number itself, e.g., -(-3) = 3, and that 0 is its own opposite.","es":"Reconocer que los signos opuestos de los números indican posiciones en lados opuestos del 0 en la recta numérica; reconocer que el opuesto del opuesto de un número es el propio número, por ejemplo, -(-3) = 3, y que 0 es su propio opuesto."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[43]}'::jsonb, true),
    ('6.NS.C.6b', '6.NS.C.6', '6.NS.6.b', 'CCSS.MATH.CONTENT.6.NS.C.6b', '{"en":"Understand signs of numbers in ordered pairs as indicating locations in quadrants of the coordinate plane; recognize that when two ordered pairs differ only by signs, the locations of the points are related by reflections across one or both axes.","es":"Comprender que los signos de los números de un par ordenado indican posiciones en los cuadrantes del plano de coordenadas; reconocer que, cuando dos pares ordenados difieren únicamente en sus signos, las posiciones de los puntos están relacionadas por reflexiones respecto de uno o ambos ejes."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[43]}'::jsonb, true),
    ('6.NS.C.6c', '6.NS.C.6', '6.NS.6.c', 'CCSS.MATH.CONTENT.6.NS.C.6c', '{"en":"Find and position integers and other rational numbers on a horizontal or vertical number line diagram; find and position pairs of integers and other rational numbers on a coordinate plane.","es":"Hallar y situar números enteros y otros números racionales en una recta numérica horizontal o vertical; hallar y situar pares de números enteros y otros números racionales en un plano de coordenadas."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[43]}'::jsonb, true),
    ('6.NS.C.7a', '6.NS.C.7', '6.NS.7.a', 'CCSS.MATH.CONTENT.6.NS.C.7a', '{"en":"Interpret statements of inequality as statements about the relative position of two numbers on a number line diagram. For example, interpret -3 > -7 as a statement that -3 is located to the right of -7 on a number line oriented from left to right.","es":"Interpretar las desigualdades como afirmaciones sobre la posición relativa de dos números en una recta numérica. Por ejemplo, interpretar -3 > -7 como la afirmación de que -3 está situado a la derecha de -7 en una recta numérica orientada de izquierda a derecha."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[43]}'::jsonb, true),
    ('6.NS.C.7b', '6.NS.C.7', '6.NS.7.b', 'CCSS.MATH.CONTENT.6.NS.C.7b', '{"en":"Write, interpret, and explain statements of order for rational numbers in real-world contexts. For example, write -3 degrees C > -7 degrees C to express the fact that -3 degrees C is warmer than -7 degrees C.","es":"Escribir, interpretar y explicar afirmaciones de orden de números racionales en contextos de la vida real. Por ejemplo, escribir -3 °C > -7 °C para expresar que -3 °C es una temperatura más cálida que -7 °C."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[43]}'::jsonb, true),
    ('6.NS.C.7c', '6.NS.C.7', '6.NS.7.c', 'CCSS.MATH.CONTENT.6.NS.C.7c', '{"en":"Understand the absolute value of a rational number as its distance from 0 on the number line; interpret absolute value as magnitude for a positive or negative quantity in a real-world situation. For example, for an account balance of -30 dollars, write |-30| = 30 to describe the size of the debt in dollars.","es":"Comprender el valor absoluto de un número racional como su distancia al 0 en la recta numérica; interpretar el valor absoluto como la magnitud de una cantidad positiva o negativa en una situación real. Por ejemplo, para un saldo de -30 dólares, escribir |-30| = 30 para describir la cuantía de la deuda en dólares."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[43]}'::jsonb, true),
    ('6.NS.C.7d', '6.NS.C.7', '6.NS.7.d', 'CCSS.MATH.CONTENT.6.NS.C.7d', '{"en":"Distinguish comparisons of absolute value from statements about order. For example, recognize that an account balance less than -30 dollars represents a debt greater than 30 dollars.","es":"Distinguir las comparaciones de valores absolutos de las afirmaciones de orden. Por ejemplo, reconocer que un saldo inferior a -30 dólares representa una deuda superior a 30 dólares."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[43]}'::jsonb, true),
    ('7.NS.A.1a', '7.NS.A.1', '7.NS.1.a', 'CCSS.MATH.CONTENT.7.NS.A.1a', '{"en":"Describe situations in which opposite quantities combine to make 0. For example, a hydrogen atom has 0 charge because its two constituents are oppositely charged.","es":"Describir situaciones en las que cantidades opuestas se combinan para dar 0. Por ejemplo, un átomo de hidrógeno tiene carga 0 porque sus dos componentes tienen cargas opuestas."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[48]}'::jsonb, true),
    ('7.NS.A.1b', '7.NS.A.1', '7.NS.1.b', 'CCSS.MATH.CONTENT.7.NS.A.1b', '{"en":"Understand p + q as the number located a distance |q| from p, in the positive or negative direction depending on whether q is positive or negative. Show that a number and its opposite have a sum of 0 (are additive inverses). Interpret sums of rational numbers by describing real-world contexts.","es":"Comprender p + q como el número situado a una distancia |q| de p, en dirección positiva o negativa según q sea positivo o negativo. Mostrar que la suma de un número y su opuesto es 0 (son inversos aditivos). Interpretar sumas de números racionales describiendo contextos de la vida real."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[48]}'::jsonb, true),
    ('7.NS.A.1c', '7.NS.A.1', '7.NS.1.c', 'CCSS.MATH.CONTENT.7.NS.A.1c', '{"en":"Understand subtraction of rational numbers as adding the additive inverse, p - q = p + (-q). Show that the distance between two rational numbers on the number line is the absolute value of their difference, and apply this principle in real-world contexts.","es":"Comprender la resta de números racionales como la suma del inverso aditivo, p - q = p + (-q). Mostrar que la distancia entre dos números racionales en la recta numérica es el valor absoluto de su diferencia y aplicar este principio en contextos de la vida real."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[48]}'::jsonb, true),
    ('7.NS.A.1d', '7.NS.A.1', '7.NS.1.d', 'CCSS.MATH.CONTENT.7.NS.A.1d', '{"en":"Apply properties of operations as strategies to add and subtract rational numbers.","es":"Aplicar las propiedades de las operaciones como estrategias para sumar y restar números racionales."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[48]}'::jsonb, true),
    ('7.NS.A.2a', '7.NS.A.2', '7.NS.2.a', 'CCSS.MATH.CONTENT.7.NS.A.2a', '{"en":"Understand that multiplication is extended from fractions to rational numbers by requiring that operations continue to satisfy the properties of operations, particularly the distributive property, leading to products such as (-1)(-1) = 1 and the rules for multiplying signed numbers. Interpret products of rational numbers by describing real-world contexts.","es":"Comprender que la multiplicación se amplía de las fracciones a los números racionales exigiendo que las operaciones sigan satisfaciendo sus propiedades, especialmente la distributiva, lo que conduce a productos como (-1)(-1) = 1 y a las reglas de multiplicación de números con signo. Interpretar productos de números racionales describiendo contextos de la vida real."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[48]}'::jsonb, true),
    ('7.NS.A.2b', '7.NS.A.2', '7.NS.2.b', 'CCSS.MATH.CONTENT.7.NS.A.2b', '{"en":"Understand that integers can be divided, provided that the divisor is not zero, and every quotient of integers (with non-zero divisor) is a rational number. If p and q are integers, then -(p/q) = (-p)/q = p/(-q). Interpret quotients of rational numbers by describing real-world contexts.","es":"Comprender que los números enteros pueden dividirse siempre que el divisor no sea cero, y que todo cociente de números enteros (con divisor distinto de cero) es un número racional. Si p y q son enteros, entonces -(p/q) = (-p)/q = p/(-q). Interpretar cocientes de números racionales describiendo contextos de la vida real."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[49]}'::jsonb, true),
    ('7.NS.A.2c', '7.NS.A.2', '7.NS.2.c', 'CCSS.MATH.CONTENT.7.NS.A.2c', '{"en":"Apply properties of operations as strategies to multiply and divide rational numbers.","es":"Aplicar las propiedades de las operaciones como estrategias para multiplicar y dividir números racionales."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[49]}'::jsonb, true),
    ('7.NS.A.2d', '7.NS.A.2', '7.NS.2.d', 'CCSS.MATH.CONTENT.7.NS.A.2d', '{"en":"Convert a rational number to a decimal using long division; know that the decimal form of a rational number terminates in 0s or eventually repeats.","es":"Convertir un número racional en decimal mediante el algoritmo de la división; saber que la expresión decimal de un número racional termina en ceros o acaba repitiéndose periódicamente."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[49]}'::jsonb, true),
    ('6.RP.A.3a', '6.RP.A.3', '6.RP.3.a', 'CCSS.MATH.CONTENT.6.RP.A.3a', '{"en":"Make tables of equivalent ratios relating quantities with whole-number measurements, find missing values in the tables, and plot the pairs of values on the coordinate plane. Use tables to compare ratios.","es":"Elaborar tablas de razones equivalentes que relacionen cantidades cuyas medidas sean números enteros no negativos, hallar los valores que faltan y representar los pares de valores en el plano de coordenadas. Utilizar tablas para comparar razones."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[42]}'::jsonb, true),
    ('6.RP.A.3b', '6.RP.A.3', '6.RP.3.b', 'CCSS.MATH.CONTENT.6.RP.A.3b', '{"en":"Solve unit rate problems including those involving unit pricing and constant speed. For example, if it took 7 hours to mow 4 lawns, then at that rate, how many lawns could be mowed in 35 hours? At what rate were lawns being mowed?","es":"Resolver problemas de tasas unitarias, incluidos los de precio unitario y velocidad constante. Por ejemplo, si se tardaron 7 horas en cortar el césped de 4 jardines, ¿de cuántos jardines podría cortarse el césped en 35 horas a ese ritmo? ¿A qué ritmo se cortaba el césped?"}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[42]}'::jsonb, true),
    ('6.RP.A.3c', '6.RP.A.3', '6.RP.3.c', 'CCSS.MATH.CONTENT.6.RP.A.3c', '{"en":"Find a percent of a quantity as a rate per 100 (e.g., 30% of a quantity means 30/100 times the quantity); solve problems involving finding the whole, given a part and the percent.","es":"Hallar un porcentaje de una cantidad como una tasa por cada 100 (por ejemplo, el 30 % de una cantidad significa 30/100 de esa cantidad); resolver problemas en los que se busca el total, dados una parte y el porcentaje."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[42]}'::jsonb, true),
    ('6.RP.A.3d', '6.RP.A.3', '6.RP.3.d', 'CCSS.MATH.CONTENT.6.RP.A.3d', '{"en":"Use ratio reasoning to convert measurement units; manipulate and transform units appropriately when multiplying or dividing quantities.","es":"Utilizar el razonamiento con razones para convertir unidades de medida; operar con las unidades y transformarlas adecuadamente al multiplicar o dividir cantidades."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[42]}'::jsonb, true),
    ('6.EE.A.2a', '6.EE.A.2', '6.EE.2.a', 'CCSS.MATH.CONTENT.6.EE.A.2a', '{"en":"Write expressions that record operations with numbers and with letters standing for numbers. For example, express the calculation \"Subtract y from 5\" as 5 - y.","es":"Escribir expresiones que registren operaciones con números y con letras que representan números. Por ejemplo, expresar el cálculo «Restar y de 5» como 5 - y."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[43]}'::jsonb, true),
    ('6.EE.A.2b', '6.EE.A.2', '6.EE.2.b', 'CCSS.MATH.CONTENT.6.EE.A.2b', '{"en":"Identify parts of an expression using mathematical terms (sum, term, product, factor, quotient, coefficient); view one or more parts of an expression as a single entity. For example, describe the expression 2 (8 + 7) as a product of two factors; view (8 + 7) as both a single entity and a sum of two terms.","es":"Identificar las partes de una expresión utilizando términos matemáticos (suma, término, producto, factor, cociente, coeficiente); considerar una o varias partes de una expresión como una sola entidad. Por ejemplo, describir la expresión 2 (8 + 7) como un producto de dos factores; considerar (8 + 7) tanto una sola entidad como una suma de dos términos."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[44]}'::jsonb, true),
    ('6.EE.A.2c', '6.EE.A.2', '6.EE.2.c', 'CCSS.MATH.CONTENT.6.EE.A.2c', '{"en":"Evaluate expressions at specific values of their variables. Include expressions that arise from formulas used in real-world problems. Perform arithmetic operations, including those involving whole-number exponents, in the conventional order when there are no parentheses to specify a particular order (Order of Operations). For example, use the formulas V = s^3 and A = 6s^2 to find the volume and surface area of a cube with sides of length s = 1/2.","es":"Evaluar expresiones para valores específicos de sus variables. Incluir expresiones procedentes de fórmulas utilizadas en problemas de la vida real. Realizar operaciones aritméticas, incluidas las que implican exponentes enteros no negativos, en el orden convencional cuando no haya paréntesis que especifiquen un orden particular (jerarquía de operaciones). Por ejemplo, utilizar las fórmulas V = s^3 y A = 6s^2 para hallar el volumen y el área superficial de un cubo de arista s = 1/2."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[44]}'::jsonb, true),
    ('7.RP.A.2a', '7.RP.A.2', '7.RP.2.a', 'CCSS.MATH.CONTENT.7.RP.A.2a', '{"en":"Decide whether two quantities are in a proportional relationship, e.g., by testing for equivalent ratios in a table or graphing on a coordinate plane and observing whether the graph is a straight line through the origin.","es":"Decidir si dos cantidades mantienen una relación proporcional, por ejemplo, comprobando si las razones de una tabla son equivalentes o representándolas en un plano de coordenadas y observando si la gráfica es una recta que pasa por el origen."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[48]}'::jsonb, true),
    ('7.RP.A.2b', '7.RP.A.2', '7.RP.2.b', 'CCSS.MATH.CONTENT.7.RP.A.2b', '{"en":"Identify the constant of proportionality (unit rate) in tables, graphs, equations, diagrams, and verbal descriptions of proportional relationships.","es":"Identificar la constante de proporcionalidad (tasa unitaria) en tablas, gráficas, ecuaciones, diagramas y descripciones verbales de relaciones proporcionales."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[48]}'::jsonb, true),
    ('7.RP.A.2c', '7.RP.A.2', '7.RP.2.c', 'CCSS.MATH.CONTENT.7.RP.A.2c', '{"en":"Represent proportional relationships by equations. For example, if total cost t is proportional to the number n of items purchased at a constant price p, the relationship between the total cost and the number of items can be expressed as t = pn.","es":"Representar relaciones proporcionales mediante ecuaciones. Por ejemplo, si el coste total t es proporcional al número n de artículos comprados a un precio constante p, la relación entre el coste total y el número de artículos puede expresarse como t = pn."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[48]}'::jsonb, true),
    ('7.RP.A.2d', '7.RP.A.2', '7.RP.2.d', 'CCSS.MATH.CONTENT.7.RP.A.2d', '{"en":"Explain what a point (x, y) on the graph of a proportional relationship means in terms of the situation, with special attention to the points (0, 0) and (1, r) where r is the unit rate.","es":"Explicar qué significa un punto (x, y) de la gráfica de una relación proporcional en términos de la situación, prestando especial atención a los puntos (0, 0) y (1, r), donde r es la tasa unitaria."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[48]}'::jsonb, true),
    ('7.EE.B.4a', '7.EE.B.4', '7.EE.4.a', 'CCSS.MATH.CONTENT.7.EE.B.4a', '{"en":"Solve word problems leading to equations of the form px + q = r and p(x + q) = r, where p, q, and r are specific rational numbers. Solve equations of these forms fluently. Compare an algebraic solution to an arithmetic solution, identifying the sequence of the operations used in each approach. For example, the perimeter of a rectangle is 54 cm. Its length is 6 cm. What is its width?","es":"Resolver problemas de enunciado que conduzcan a ecuaciones de la forma px + q = r y p(x + q) = r, donde p, q y r son números racionales específicos. Resolver con fluidez ecuaciones de estas formas. Comparar una solución algebraica con una aritmética, identificando la secuencia de operaciones utilizada en cada enfoque. Por ejemplo, el perímetro de un rectángulo es de 54 cm y su longitud es de 6 cm. ¿Cuál es su anchura?"}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[49]}'::jsonb, true),
    ('7.EE.B.4b', '7.EE.B.4', '7.EE.4.b', 'CCSS.MATH.CONTENT.7.EE.B.4b', '{"en":"Solve word problems leading to inequalities of the form px + q > r or px + q < r, where p, q, and r are specific rational numbers. Graph the solution set of the inequality and interpret it in the context of the problem. For example: As a salesperson, you are paid $50 per week plus $3 per sale. This week you want your pay to be at least $100. Write an inequality for the number of sales you need to make, and describe the solutions.","es":"Resolver problemas de enunciado que conduzcan a inecuaciones de la forma px + q > r o px + q < r, donde p, q y r son números racionales específicos. Representar gráficamente el conjunto de soluciones e interpretarlo en el contexto del problema. Por ejemplo: como vendedor, se reciben 50 dólares por semana más 3 dólares por venta. Esta semana se desea cobrar al menos 100 dólares. Escribir una inecuación para el número de ventas necesarias y describir las soluciones."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[49]}'::jsonb, true),
    ('8.EE.C.7a', '8.EE.C.7', '8.EE.7.a', 'CCSS.MATH.CONTENT.8.EE.C.7a', '{"en":"Give examples of linear equations in one variable with one solution, infinitely many solutions, or no solutions. Show which of these possibilities is the case by successively transforming the given equation into simpler forms, until an equivalent equation of the form x = a, a = a, or a = b results (where a and b are different numbers).","es":"Dar ejemplos de ecuaciones lineales de una variable con una solución, infinitas soluciones o ninguna solución. Mostrar cuál de estas posibilidades se da transformando sucesivamente la ecuación en formas más sencillas hasta obtener una ecuación equivalente de la forma x = a, a = a o a = b (donde a y b son números distintos)."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[54]}'::jsonb, true),
    ('8.EE.C.7b', '8.EE.C.7', '8.EE.7.b', 'CCSS.MATH.CONTENT.8.EE.C.7b', '{"en":"Solve linear equations with rational number coefficients, including equations whose solutions require expanding expressions using the distributive property and collecting like terms.","es":"Resolver ecuaciones lineales con coeficientes racionales, incluidas aquellas cuya solución requiere desarrollar expresiones mediante la propiedad distributiva y reducir términos semejantes."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[54]}'::jsonb, true),
    ('8.EE.C.8a', '8.EE.C.8', '8.EE.8.a', 'CCSS.MATH.CONTENT.8.EE.C.8a', '{"en":"Understand that solutions to a system of two linear equations in two variables correspond to points of intersection of their graphs, because points of intersection satisfy both equations simultaneously.","es":"Comprender que las soluciones de un sistema de dos ecuaciones lineales con dos variables corresponden a los puntos de intersección de sus gráficas, porque esos puntos satisfacen ambas ecuaciones simultáneamente."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[55]}'::jsonb, true),
    ('8.EE.C.8b', '8.EE.C.8', '8.EE.8.b', 'CCSS.MATH.CONTENT.8.EE.C.8b', '{"en":"Solve systems of two linear equations in two variables algebraically, and estimate solutions by graphing the equations. Solve simple cases by inspection. For example, 3x + 2y = 5 and 3x + 2y = 6 have no solution because 3x + 2y cannot simultaneously be 5 and 6.","es":"Resolver algebraicamente sistemas de dos ecuaciones lineales con dos variables y estimar las soluciones representando las ecuaciones. Resolver casos sencillos por inspección. Por ejemplo, 3x + 2y = 5 y 3x + 2y = 6 no tienen solución porque 3x + 2y no puede ser simultáneamente 5 y 6."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[55]}'::jsonb, true),
    ('8.EE.C.8c', '8.EE.C.8', '8.EE.8.c', 'CCSS.MATH.CONTENT.8.EE.C.8c', '{"en":"Solve real-world and mathematical problems leading to two linear equations in two variables. For example, given coordinates for two pairs of points, determine whether the line through the first pair of points intersects the line through the second pair.","es":"Resolver problemas de la vida real y matemáticos que conduzcan a dos ecuaciones lineales con dos variables. Por ejemplo, dadas las coordenadas de dos pares de puntos, determinar si la recta que pasa por el primer par corta a la recta que pasa por el segundo."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[55]}'::jsonb, true),
    ('HSA-SSE.A.1a', 'HSA-SSE.A.1', 'A-SSE.1.a', 'CCSS.MATH.CONTENT.HSA-SSE.A.1a', '{"en":"Interpret parts of an expression, such as terms, factors, and coefficients.","es":"Interpretar partes de una expresión, como términos, factores y coeficientes."}'::jsonb, '{"modeling":true,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[64]}'::jsonb, true),
    ('HSA-SSE.A.1b', 'HSA-SSE.A.1', 'A-SSE.1.b', 'CCSS.MATH.CONTENT.HSA-SSE.A.1b', '{"en":"Interpret complicated expressions by viewing one or more of their parts as a single entity. For example, interpret P(1+r)^n as the product of P and a factor not depending on P.","es":"Interpretar expresiones complejas considerando una o varias de sus partes como una sola entidad. Por ejemplo, interpretar P(1+r)^n como el producto de P por un factor que no depende de P."}'::jsonb, '{"modeling":true,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[64]}'::jsonb, true),
    ('HSA-SSE.B.3a', 'HSA-SSE.B.3', 'A-SSE.3.a', 'CCSS.MATH.CONTENT.HSA-SSE.B.3a', '{"en":"Factor a quadratic expression to reveal the zeros of the function it defines.","es":"Factorizar una expresión cuadrática para revelar los ceros de la función que define."}'::jsonb, '{"modeling":true,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[64]}'::jsonb, true),
    ('HSA-SSE.B.3b', 'HSA-SSE.B.3', 'A-SSE.3.b', 'CCSS.MATH.CONTENT.HSA-SSE.B.3b', '{"en":"Complete the square in a quadratic expression to reveal the maximum or minimum value of the function it defines.","es":"Completar el cuadrado en una expresión cuadrática para revelar el valor máximo o mínimo de la función que define."}'::jsonb, '{"modeling":true,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[64]}'::jsonb, true),
    ('HSA-SSE.B.3c', 'HSA-SSE.B.3', 'A-SSE.3.c', 'CCSS.MATH.CONTENT.HSA-SSE.B.3c', '{"en":"Use the properties of exponents to transform expressions for exponential functions. For example the expression 1.15^t can be rewritten as (1.15^(1/12))^(12t) ≈ 1.012^(12t) to reveal the approximate equivalent monthly interest rate if the annual rate is 15%.","es":"Utilizar las propiedades de los exponentes para transformar expresiones de funciones exponenciales. Por ejemplo, la expresión 1.15^t puede reescribirse como (1.15^(1/12))^(12t) ≈ 1.012^(12t) para revelar el tipo de interés mensual equivalente aproximado cuando el tipo anual es del 15 %."}'::jsonb, '{"modeling":true,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[64]}'::jsonb, true),
    ('HSA-REI.B.4a', 'HSA-REI.B.4', 'A-REI.4.a', 'CCSS.MATH.CONTENT.HSA-REI.B.4a', '{"en":"Use the method of completing the square to transform any quadratic equation in x into an equation of the form (x - p)^2 = q that has the same solutions. Derive the quadratic formula from this form.","es":"Utilizar el método de completar el cuadrado para transformar cualquier ecuación cuadrática en x en una ecuación de la forma (x - p)^2 = q con las mismas soluciones. Deducir la fórmula general de la ecuación cuadrática a partir de esta forma."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[65]}'::jsonb, true),
    ('HSA-REI.B.4b', 'HSA-REI.B.4', 'A-REI.4.b', 'CCSS.MATH.CONTENT.HSA-REI.B.4b', '{"en":"Solve quadratic equations by inspection (e.g., for x^2 = 49), taking square roots, completing the square, the quadratic formula and factoring, as appropriate to the initial form of the equation. Recognize when the quadratic formula gives complex solutions and write them as a ± bi for real numbers a and b.","es":"Resolver ecuaciones cuadráticas por inspección (por ejemplo, x^2 = 49), extrayendo raíces cuadradas, completando el cuadrado, mediante la fórmula general o factorizando, según la forma inicial de la ecuación. Reconocer cuándo la fórmula general produce soluciones complejas y escribirlas como a ± bi, con a y b reales."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[65]}'::jsonb, true),
    ('HSF-IF.C.7a', 'HSF-IF.C.7', 'F-IF.7.a', 'CCSS.MATH.CONTENT.HSF-IF.C.7a', '{"en":"Graph linear and quadratic functions and show intercepts, maxima, and minima.","es":"Representar funciones lineales y cuadráticas y mostrar las intersecciones con los ejes, los máximos y los mínimos."}'::jsonb, '{"modeling":true,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[69]}'::jsonb, true),
    ('HSF-IF.C.7b', 'HSF-IF.C.7', 'F-IF.7.b', 'CCSS.MATH.CONTENT.HSF-IF.C.7b', '{"en":"Graph square root, cube root, and piecewise-defined functions, including step functions and absolute value functions.","es":"Representar funciones raíz cuadrada, raíz cúbica y definidas a trozos, incluidas funciones escalonadas y de valor absoluto."}'::jsonb, '{"modeling":true,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[69]}'::jsonb, true),
    ('HSF-IF.C.7e', 'HSF-IF.C.7', 'F-IF.7.e', 'CCSS.MATH.CONTENT.HSF-IF.C.7e', '{"en":"Graph exponential and logarithmic functions, showing intercepts and end behavior, and trigonometric functions, showing period, midline, and amplitude.","es":"Representar funciones exponenciales y logarítmicas mostrando las intersecciones con los ejes y el comportamiento en los extremos del dominio, y funciones trigonométricas mostrando el período, la línea media y la amplitud."}'::jsonb, '{"modeling":true,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[69]}'::jsonb, true),
    ('HSF-IF.C.8a', 'HSF-IF.C.8', 'F-IF.8.a', 'CCSS.MATH.CONTENT.HSF-IF.C.8a', '{"en":"Use the process of factoring and completing the square in a quadratic function to show zeros, extreme values, and symmetry of the graph, and interpret these in terms of a context.","es":"Utilizar la factorización y el método de completar el cuadrado en una función cuadrática para mostrar los ceros, los valores extremos y la simetría de la gráfica e interpretarlos en términos de un contexto."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[69]}'::jsonb, true),
    ('HSF-IF.C.8b', 'HSF-IF.C.8', 'F-IF.8.b', 'CCSS.MATH.CONTENT.HSF-IF.C.8b', '{"en":"Use the properties of exponents to interpret expressions for exponential functions. For example, identify percent rate of change in functions such as y = (1.02)^t, y = (0.97)^t, y = (1.01)^(12t), y = (1.2)^(t/10), and classify them as representing exponential growth or decay.","es":"Utilizar las propiedades de los exponentes para interpretar expresiones de funciones exponenciales. Por ejemplo, identificar la tasa porcentual de variación en funciones como y = (1.02)^t, y = (0.97)^t, y = (1.01)^(12t), y = (1.2)^(t/10), y clasificarlas según representen crecimiento o decrecimiento exponencial."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[69]}'::jsonb, true),
    ('HSF-BF.A.1a', 'HSF-BF.A.1', 'F-BF.1.a', 'CCSS.MATH.CONTENT.HSF-BF.A.1a', '{"en":"Determine an explicit expression, a recursive process, or steps for calculation from a context.","es":"Determinar una expresión explícita, un proceso recursivo o pasos de cálculo a partir de un contexto."}'::jsonb, '{"modeling":true,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[70]}'::jsonb, true),
    ('HSF-BF.A.1b', 'HSF-BF.A.1', 'F-BF.1.b', 'CCSS.MATH.CONTENT.HSF-BF.A.1b', '{"en":"Combine standard function types using arithmetic operations. For example, build a function that models the temperature of a cooling body by adding a constant function to a decaying exponential, and relate these functions to the model.","es":"Combinar tipos habituales de funciones mediante operaciones aritméticas. Por ejemplo, construir una función que modele la temperatura de un cuerpo que se enfría sumando una función constante a una exponencial decreciente y relacionar estas funciones con el modelo."}'::jsonb, '{"modeling":true,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[70]}'::jsonb, true),
    ('HSF-BF.B.4a', 'HSF-BF.B.4', 'F-BF.4.a', 'CCSS.MATH.CONTENT.HSF-BF.B.4a', '{"en":"Solve an equation of the form f(x) = c for a simple function f that has an inverse and write an expression for the inverse. For example, f(x) = 2x^3 or f(x) = (x+1)/(x-1) for x ≠ 1.","es":"Resolver una ecuación de la forma f(x) = c para una función sencilla f que tenga inversa y escribir una expresión de la inversa. Por ejemplo, f(x) = 2x^3 o f(x) = (x+1)/(x-1) para x ≠ 1."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[70]}'::jsonb, true),
    ('HSF-LE.A.1a', 'HSF-LE.A.1', 'F-LE.1.a', 'CCSS.MATH.CONTENT.HSF-LE.A.1a', '{"en":"Prove that linear functions grow by equal differences over equal intervals, and that exponential functions grow by equal factors over equal intervals.","es":"Demostrar que las funciones lineales crecen mediante diferencias iguales en intervalos iguales y que las funciones exponenciales crecen mediante factores iguales en intervalos iguales."}'::jsonb, '{"modeling":true,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[70]}'::jsonb, true),
    ('HSF-LE.A.1b', 'HSF-LE.A.1', 'F-LE.1.b', 'CCSS.MATH.CONTENT.HSF-LE.A.1b', '{"en":"Recognize situations in which one quantity changes at a constant rate per unit interval relative to another.","es":"Reconocer situaciones en las que una cantidad cambia a una tasa constante por intervalo unitario respecto de otra."}'::jsonb, '{"modeling":true,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[70]}'::jsonb, true),
    ('HSF-LE.A.1c', 'HSF-LE.A.1', 'F-LE.1.c', 'CCSS.MATH.CONTENT.HSF-LE.A.1c', '{"en":"Recognize situations in which a quantity grows or decays by a constant percent rate per unit interval relative to another.","es":"Reconocer situaciones en las que una cantidad crece o decrece a una tasa porcentual constante por intervalo unitario respecto de otra."}'::jsonb, '{"modeling":true,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[70]}'::jsonb, true),
    ('8.G.A.1a', '8.G.A.1', '8.G.1.a', 'CCSS.MATH.CONTENT.8.G.A.1a', '{"en":"Lines are taken to lines, and line segments to line segments of the same length.","es":"Las rectas se transforman en rectas y los segmentos en segmentos de la misma longitud."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[55]}'::jsonb, true),
    ('8.G.A.1b', '8.G.A.1', '8.G.1.b', 'CCSS.MATH.CONTENT.8.G.A.1b', '{"en":"Angles are taken to angles of the same measure.","es":"Los ángulos se transforman en ángulos de la misma medida."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[55]}'::jsonb, true),
    ('8.G.A.1c', '8.G.A.1', '8.G.1.c', 'CCSS.MATH.CONTENT.8.G.A.1c', '{"en":"Parallel lines are taken to parallel lines.","es":"Las rectas paralelas se transforman en rectas paralelas."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[55]}'::jsonb, true),
    ('HSG-SRT.A.1a', 'HSG-SRT.A.1', 'G-SRT.1.a', 'CCSS.MATH.CONTENT.HSG-SRT.A.1a', '{"en":"A dilation takes a line not passing through the center of the dilation to a parallel line, and leaves a line passing through the center unchanged.","es":"Una homotecia transforma una recta que no pasa por su centro en una recta paralela y deja inalterada una recta que pasa por el centro."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[77]}'::jsonb, true),
    ('HSG-SRT.A.1b', 'HSG-SRT.A.1', 'G-SRT.1.b', 'CCSS.MATH.CONTENT.HSG-SRT.A.1b', '{"en":"The dilation of a line segment is longer or shorter in the ratio given by the scale factor.","es":"La imagen de un segmento por una homotecia es más larga o más corta según la razón dada por el factor de escala."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[77]}'::jsonb, true),
    ('6.SP.B.5a', '6.SP.B.5', '6.SP.5.a', 'CCSS.MATH.CONTENT.6.SP.B.5a', '{"en":"Reporting the number of observations.","es":"La indicación del número de observaciones."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[45]}'::jsonb, true),
    ('6.SP.B.5b', '6.SP.B.5', '6.SP.5.b', 'CCSS.MATH.CONTENT.6.SP.B.5b', '{"en":"Describing the nature of the attribute under investigation, including how it was measured and its units of measurement.","es":"La descripción de la naturaleza del atributo investigado, incluida la forma en que se midió y sus unidades de medida."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[45]}'::jsonb, true),
    ('6.SP.B.5c', '6.SP.B.5', '6.SP.5.c', 'CCSS.MATH.CONTENT.6.SP.B.5c', '{"en":"Giving quantitative measures of center (median and/or mean) and variability (interquartile range and/or mean absolute deviation), as well as describing any overall pattern and any striking deviations from the overall pattern with reference to the context in which the data were gathered.","es":"La aportación de medidas cuantitativas de centralización (mediana o media) y variabilidad (rango intercuartílico o desviación absoluta media), así como la descripción de cualquier patrón general y de las desviaciones llamativas respecto de ese patrón, con referencia al contexto en el que se recogieron los datos."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[45]}'::jsonb, true),
    ('6.SP.B.5d', '6.SP.B.5', '6.SP.5.d', 'CCSS.MATH.CONTENT.6.SP.B.5d', '{"en":"Relating the choice of measures of center and variability to the shape of the data distribution and the context in which the data were gathered.","es":"La relación entre la elección de medidas de centralización y variabilidad y la forma de la distribución de los datos y el contexto en que se recogieron."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[45]}'::jsonb, true),
    ('7.SP.C.7a', '7.SP.C.7', '7.SP.7.a', 'CCSS.MATH.CONTENT.7.SP.C.7a', '{"en":"Develop a uniform probability model by assigning equal probability to all outcomes, and use the model to determine probabilities of events. For example, if a student is selected at random from a class, find the probability that Jane will be selected and the probability that a girl will be selected.","es":"Desarrollar un modelo de probabilidad uniforme asignando la misma probabilidad a todos los resultados y utilizarlo para determinar probabilidades de sucesos. Por ejemplo, si se selecciona al azar a un estudiante de una clase, hallar la probabilidad de que se seleccione a Jane y la probabilidad de que se seleccione a una chica."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[51]}'::jsonb, true),
    ('7.SP.C.7b', '7.SP.C.7', '7.SP.7.b', 'CCSS.MATH.CONTENT.7.SP.C.7b', '{"en":"Develop a probability model (which may not be uniform) by observing frequencies in data generated from a chance process. For example, find the approximate probability that a spinning penny will land heads up or that a tossed paper cup will land open-end down. Do the outcomes for the spinning penny appear to be equally likely based on the observed frequencies?","es":"Desarrollar un modelo de probabilidad (que puede no ser uniforme) observando frecuencias en datos generados por un proceso aleatorio. Por ejemplo, hallar la probabilidad aproximada de que una moneda de un centavo puesta a girar caiga con la cara hacia arriba o de que un vaso de papel lanzado al aire caiga con la abertura hacia abajo. Según las frecuencias observadas, ¿parecen igualmente probables los resultados de la moneda que gira?"}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[51]}'::jsonb, true),
    ('7.SP.C.8a', '7.SP.C.8', '7.SP.8.a', 'CCSS.MATH.CONTENT.7.SP.C.8a', '{"en":"Understand that, just as with simple events, the probability of a compound event is the fraction of outcomes in the sample space for which the compound event occurs.","es":"Comprender que, al igual que en los sucesos simples, la probabilidad de un suceso compuesto es la fracción de los resultados del espacio muestral en los que ocurre ese suceso."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[51]}'::jsonb, true),
    ('7.SP.C.8b', '7.SP.C.8', '7.SP.8.b', 'CCSS.MATH.CONTENT.7.SP.C.8b', '{"en":"Represent sample spaces for compound events using methods such as organized lists, tables and tree diagrams. For an event described in everyday language (e.g., \"rolling double sixes\"), identify the outcomes in the sample space which compose the event.","es":"Representar espacios muestrales de sucesos compuestos mediante métodos como listas organizadas, tablas y diagramas de árbol. Para un suceso descrito en lenguaje cotidiano (por ejemplo, «sacar dos seises»), identificar los resultados del espacio muestral que lo componen."}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[51]}'::jsonb, true),
    ('7.SP.C.8c', '7.SP.C.8', '7.SP.8.c', 'CCSS.MATH.CONTENT.7.SP.C.8c', '{"en":"Design and use a simulation to generate frequencies for compound events. For example, use random digits as a simulation tool to approximate the answer to the question: If 40% of donors have type A blood, what is the probability that it will take at least 4 donors to find one with type A blood?","es":"Diseñar y utilizar una simulación para generar frecuencias de sucesos compuestos. Por ejemplo, utilizar dígitos aleatorios como herramienta de simulación para aproximar la respuesta a la pregunta: si el 40 % de los donantes tiene sangre del grupo A, ¿cuál es la probabilidad de que se necesiten al menos 4 donantes para encontrar uno con sangre del grupo A?"}'::jsonb, '{"modeling":false,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[51]}'::jsonb, true),
    ('HSS-ID.B.6a', 'HSS-ID.B.6', 'S-ID.6.a', 'CCSS.MATH.CONTENT.HSS-ID.B.6a', '{"en":"Fit a function to the data; use functions fitted to data to solve problems in the context of the data. Use given functions or choose a function suggested by the context. Emphasize linear, quadratic, and exponential models.","es":"Ajustar una función a los datos; utilizar funciones ajustadas a datos para resolver problemas en su contexto. Utilizar funciones dadas o elegir una función sugerida por el contexto. Dar énfasis a modelos lineales, cuadráticos y exponenciales."}'::jsonb, '{"modeling":true,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[81]}'::jsonb, true),
    ('HSS-ID.B.6b', 'HSS-ID.B.6', 'S-ID.6.b', 'CCSS.MATH.CONTENT.HSS-ID.B.6b', '{"en":"Informally assess the fit of a function by plotting and analyzing residuals.","es":"Evaluar informalmente el ajuste de una función representando y analizando residuos."}'::jsonb, '{"modeling":true,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[81]}'::jsonb, true),
    ('HSS-ID.B.6c', 'HSS-ID.B.6', 'S-ID.6.c', 'CCSS.MATH.CONTENT.HSS-ID.B.6c', '{"en":"Fit a linear function for a scatter plot that suggests a linear association.","es":"Ajustar una función lineal a un diagrama de dispersión que sugiera una asociación lineal."}'::jsonb, '{"modeling":true,"plus":false}'::jsonb, '{"sourceId":"ccss","pages":[81]}'::jsonb, true)
