    ('grade-9', 'HSA-SSE.A.1', 'listed', '[{"targetIds":["HSA-SSE.A.1a","HSA-SSE.A.1b"],"extent":"limited","source":{"sourceId":"appendix-a","pages":[53]},"scope":{"en":"Limit to linear expressions and exponential expressions with integer exponents.","es":"Limitar a expresiones lineales y expresiones exponenciales con exponentes enteros."}}]'::jsonb),
    ('grade-9', 'HSA-CED.A.1', 'listed', '[{"targetIds":["HSA-CED.A.1"],"extent":"limited","source":{"sourceId":"appendix-a","pages":[53]},"scope":{"en":"Limit to linear and exponential equations; exponential situations require evaluation at integer inputs.","es":"Limitar a ecuaciones lineales y exponenciales; las situaciones exponenciales requieren evaluación con entradas enteras."}}]'::jsonb),
