    ('grade-9', 'HSA-CED.A.3', 'listed', '[{"targetIds":["HSA-CED.A.3"],"extent":"limited","source":{"sourceId":"appendix-a","pages":[53]},"scope":{"en":"Limit constraints to linear equations and inequalities.","es":"Limitar las restricciones a ecuaciones e inecuaciones lineales."}}]'::jsonb),
    ('grade-9', 'HSA-CED.A.4', 'listed', '[{"targetIds":["HSA-CED.A.4"],"extent":"limited","source":{"sourceId":"appendix-a","pages":[53]},"scope":{"en":"Limit rearrangement to formulas with a linear focus.","es":"Limitar el despeje a fórmulas con enfoque lineal."}}]'::jsonb),
    ('grade-9', 'HSA-REI.A.1', 'listed', '[{"targetIds":["HSA-REI.A.1"],"extent":"limited","source":{"sourceId":"appendix-a","pages":[57]},"scope":{"en":"Master justification of the steps for linear equations and prepare to extend that reasoning. Solving exponential equations with logarithms belongs to Mathematics III.","es":"Dominar la justificación de los pasos en ecuaciones lineales y preparar la ampliación de ese razonamiento. La resolución de ecuaciones exponenciales con logaritmos corresponde a Matemáticas III."}}]'::jsonb),
    ('grade-9', 'HSA-REI.B.3', 'listed', '[{"targetIds":["HSA-REI.B.3"],"extent":"full","source":{"sourceId":"appendix-a","pages":[57]},"scope":{"en":"Include linear inequalities and literal equations linear in the variable being solved for. Instruction also includes simple exponential equations solved using exponent laws, such as 5^x = 125 or 2^x = 1/16.","es":"Incluir inecuaciones lineales y ecuaciones literales lineales en la variable que se despeja. La enseñanza también incluye ecuaciones exponenciales sencillas resueltas con las leyes de exponentes, como 5^x = 125 o 2^x = 1/16."}}]'::jsonb),
    ('grade-9', 'HSA-REI.C.5', 'listed', '[{"targetIds":["HSA-REI.C.5"],"extent":"full","source":{"sourceId":"appendix-a","pages":[57]},"scope":{"en":"Justify methods for linear systems in two variables, including coincident lines with infinitely many solutions and parallel lines with no solution; connect to slope criteria.","es":"Justificar métodos para sistemas lineales de dos variables, incluidas rectas coincidentes con infinitas soluciones y paralelas sin solución; conectar con los criterios de pendientes."}}]'::jsonb),
    ('grade-9', 'HSA-REI.C.6', 'listed', '[{"targetIds":["HSA-REI.C.6"],"extent":"full","source":{"sourceId":"appendix-a","pages":[57]},"scope":{"en":"Justify methods for linear systems in two variables, including coincident lines with infinitely many solutions and parallel lines with no solution; connect to slope criteria.","es":"Justificar métodos para sistemas lineales de dos variables, incluidas rectas coincidentes con infinitas soluciones y paralelas sin solución; conectar con los criterios de pendientes."}}]'::jsonb),
    ('grade-9', 'HSA-REI.D.10', 'listed', '[{"targetIds":["HSA-REI.D.10"],"extent":"limited","source":{"sourceId":"appendix-a","pages":[54]},"scope":{"en":"Focus on graphical representation and solution of linear and exponential equations.","es":"Centrarse en la representación y resolución gráfica de ecuaciones lineales y exponenciales."}}]'::jsonb),
    ('grade-9', 'HSA-REI.D.11', 'listed', '[{"targetIds":["HSA-REI.D.11"],"extent":"limited","source":{"sourceId":"appendix-a","pages":[54]},"scope":{"en":"Focus on graphical representation and solution of linear and exponential equations.","es":"Centrarse en la representación y resolución gráfica de ecuaciones lineales y exponenciales."}}]'::jsonb),
    ('grade-9', 'HSA-REI.D.12', 'listed', '[{"targetIds":["HSA-REI.D.12"],"extent":"full","source":{"sourceId":"appendix-a","pages":[54]},"scope":{"en":"Represent half-planes and systems of linear inequalities in two variables.","es":"Representar semiplanos y sistemas de inecuaciones lineales de dos variables."}}]'::jsonb),
    ('grade-9', 'HSF-IF.A.1', 'listed', '[{"targetIds":["HSF-IF.A.1"],"extent":"full","source":{"sourceId":"appendix-a","pages":[54]},"scope":{"en":"Develop function concepts and notation through varied situations, with examples from linear and exponential functions. Connect arithmetic and geometric sequences to functions and to F-BF.2; avoid detailed analysis of a particular function class at this stage.","es":"Desarrollar los conceptos y la notación de funciones mediante situaciones variadas, con ejemplos de funciones lineales y exponenciales. Conectar las sucesiones aritméticas y geométricas con las funciones y con F-BF.2; evitar en esta etapa el análisis detallado de una clase particular de funciones."}}]'::jsonb),
    ('grade-9', 'HSF-IF.A.2', 'listed', '[{"targetIds":["HSF-IF.A.2"],"extent":"full","source":{"sourceId":"appendix-a","pages":[54]},"scope":{"en":"Develop function concepts and notation through varied situations, with examples from linear and exponential functions. Connect arithmetic and geometric sequences to functions and to F-BF.2; avoid detailed analysis of a particular function class at this stage.","es":"Desarrollar los conceptos y la notación de funciones mediante situaciones variadas, con ejemplos de funciones lineales y exponenciales. Conectar las sucesiones aritméticas y geométricas con las funciones y con F-BF.2; evitar en esta etapa el análisis detallado de una clase particular de funciones."}}]'::jsonb),
    ('grade-9', 'HSF-IF.A.3', 'listed', '[{"targetIds":["HSF-IF.A.3"],"extent":"full","source":{"sourceId":"appendix-a","pages":[54]},"scope":{"en":"Develop function concepts and notation through varied situations, with examples from linear and exponential functions. Connect arithmetic and geometric sequences to functions and to F-BF.2; avoid detailed analysis of a particular function class at this stage.","es":"Desarrollar los conceptos y la notación de funciones mediante situaciones variadas, con ejemplos de funciones lineales y exponenciales. Conectar las sucesiones aritméticas y geométricas con las funciones y con F-BF.2; evitar en esta etapa el análisis detallado de una clase particular de funciones."}}]'::jsonb),
    ('grade-9', 'HSF-IF.B.4', 'listed', '[{"targetIds":["HSF-IF.B.4"],"extent":"limited","source":{"sourceId":"appendix-a","pages":[55]},"scope":{"en":"Focus on contextual interpretation of linear and exponential functions. The note references N-RN.1 and N-RN.2 before exponential models with continuous domains; these references do not assign those standards to Mathematics I.","es":"Centrarse en la interpretación contextual de funciones lineales y exponenciales. La nota remite a N-RN.1 y N-RN.2 antes de tratar modelos exponenciales de dominio continuo; estas referencias no asignan dichos estándares a Matemáticas I."}}]'::jsonb)
INSERT INTO public.curriculum_course_standards (course_id, standard_id, inclusion, coverage) VALUES
    ('grade-9', 'HSF-IF.B.5', 'listed', '[{"targetIds":["HSF-IF.B.5"],"extent":"limited","source":{"sourceId":"appendix-a","pages":[55]},"scope":{"en":"Focus on contextual interpretation of linear and exponential functions. The note references N-RN.1 and N-RN.2 before exponential models with continuous domains; these references do not assign those standards to Mathematics I.","es":"Centrarse en la interpretación contextual de funciones lineales y exponenciales. La nota remite a N-RN.1 y N-RN.2 antes de tratar modelos exponenciales de dominio continuo; estas referencias no asignan dichos estándares a Matemáticas I."}}]'::jsonb),
    ('grade-9', 'HSF-IF.B.6', 'listed', '[{"targetIds":["HSF-IF.B.6"],"extent":"limited","source":{"sourceId":"appendix-a","pages":[55]},"scope":{"en":"Focus on average rates of change of linear functions and on intervals of exponential functions whose domain is a subset of the integers.","es":"Centrarse en tasas de variación media de funciones lineales y en intervalos de funciones exponenciales cuyo dominio es un subconjunto de los enteros."}}]'::jsonb),
    ('grade-9', 'HSF-IF.C.7', 'listed', '[{"targetIds":["HSF-IF.C.7a"],"extent":"limited","source":{"sourceId":"appendix-a","pages":[55]},"scope":{"en":"Graph linear functions; the quadratic portion of this substandard is treated in Mathematics II.","es":"Representar funciones lineales; la parte cuadrática de este subestándar se trata en Matemáticas II."}},{"targetIds":["HSF-IF.C.7e"],"extent":"limited","source":{"sourceId":"appendix-a","pages":[55]},"scope":{"en":"Graph exponential functions only; logarithmic and trigonometric portions of this substandard are outside this course treatment.","es":"Representar únicamente funciones exponenciales; las partes logarítmica y trigonométrica de este subestándar quedan fuera del tratamiento de este curso."}}]'::jsonb),
    ('grade-9', 'HSF-IF.C.9', 'listed', '[{"targetIds":["HSF-IF.C.9"],"extent":"limited","source":{"sourceId":"appendix-a","pages":[55]},"scope":{"en":"Compare linear and exponential functions, including two functions both presented algebraically.","es":"Comparar funciones lineales y exponenciales, incluidas dos funciones presentadas ambas algebraicamente."}}]'::jsonb),
    ('grade-9', 'HSF-BF.A.1', 'listed', '[{"targetIds":["HSF-BF.A.1a","HSF-BF.A.1b"],"extent":"limited","source":{"sourceId":"appendix-a","pages":[55]},"scope":{"en":"Limit function building to linear and exponential functions. Connect arithmetic sequences to linear functions and geometric sequences to exponential functions; sequence domains are integer-valued.","es":"Limitar la construcción de funciones a lineales y exponenciales. Conectar las sucesiones aritméticas con las funciones lineales y las geométricas con las exponenciales; los dominios de las sucesiones son enteros."}}]'::jsonb),
    ('grade-9', 'HSF-BF.A.2', 'listed', '[{"targetIds":["HSF-BF.A.2"],"extent":"limited","source":{"sourceId":"appendix-a","pages":[55]},"scope":{"en":"Limit function building to linear and exponential functions. Connect arithmetic sequences to linear functions and geometric sequences to exponential functions; sequence domains are integer-valued.","es":"Limitar la construcción de funciones a lineales y exponenciales. Conectar las sucesiones aritméticas con las funciones lineales y las geométricas con las exponenciales; los dominios de las sucesiones son enteros."}}]'::jsonb),
    ('grade-9', 'HSF-BF.B.3', 'listed', '[{"targetIds":["HSF-BF.B.3"],"extent":"limited","source":{"sourceId":"appendix-a","pages":[55]},"scope":{"en":"Focus on vertical translations of linear and exponential graphs and relate a linear function''s vertical translation to its y-intercept. Other linear graph transformations may be used, but their effects can be difficult to distinguish at this level.","es":"Centrarse en traslaciones verticales de gráficas lineales y exponenciales y relacionar la traslación vertical de una función lineal con su ordenada en el origen. Pueden utilizarse otras transformaciones de gráficas lineales, aunque sus efectos pueden resultar difíciles de distinguir en este nivel."}}]'::jsonb),
    ('grade-9', 'HSF-LE.A.1', 'listed', '[{"targetIds":["HSF-LE.A.1a","HSF-LE.A.1b","HSF-LE.A.1c"],"extent":"full","source":{"sourceId":"appendix-a","pages":[56]},"scope":{"en":"Distinguish and construct linear and exponential models, including arithmetic and geometric sequences.","es":"Distinguir y construir modelos lineales y exponenciales, incluidas sucesiones aritméticas y geométricas."}}]'::jsonb),
    ('grade-9', 'HSF-LE.A.2', 'listed', '[{"targetIds":["HSF-LE.A.2"],"extent":"full","source":{"sourceId":"appendix-a","pages":[56]},"scope":{"en":"Distinguish and construct linear and exponential models, including arithmetic and geometric sequences.","es":"Distinguir y construir modelos lineales y exponenciales, incluidas sucesiones aritméticas y geométricas."}}]'::jsonb),
    ('grade-9', 'HSF-LE.A.3', 'listed', '[{"targetIds":["HSF-LE.A.3"],"extent":"limited","source":{"sourceId":"appendix-a","pages":[56]},"scope":{"en":"Limit growth comparisons to exponential and linear models; quadratic growth is added in Mathematics II.","es":"Limitar las comparaciones de crecimiento a modelos exponenciales y lineales; el crecimiento cuadrático se incorpora en Matemáticas II."}}]'::jsonb),
