    ('grade-10', 'HSA-SSE.A.1a', 'listed', '[{"targetIds":["HSA-SSE.A.1a","HSA-SSE.A.1b"],"extent":"limited","source":{"sourceId":"appendix-a","pages":[66]},"scope":{"en":"Focus on quadratic and exponential expressions. In A-SSE.1b extend integer exponents to rational exponents, emphasizing square and cube roots.","es":"Centrarse en expresiones cuadráticas y exponenciales. En A-SSE.1b ampliar los exponentes enteros a racionales, con énfasis en raíces cuadradas y cúbicas."}}]'::jsonb),
    ('grade-10', 'HSA-SSE.A.1b', 'listed', '[{"targetIds":["HSA-SSE.A.1a","HSA-SSE.A.1b"],"extent":"limited","source":{"sourceId":"appendix-a","pages":[66]},"scope":{"en":"Focus on quadratic and exponential expressions. In A-SSE.1b extend integer exponents to rational exponents, emphasizing square and cube roots.","es":"Centrarse en expresiones cuadráticas y exponenciales. En A-SSE.1b ampliar los exponentes enteros a racionales, con énfasis en raíces cuadradas y cúbicas."}}]'::jsonb),
