    ('grade-10', 'HSF-IF.C.7a', 'listed', '[{"targetIds":["HSF-IF.C.7a"],"extent":"full","source":{"sourceId":"appendix-a","pages":[64]},"scope":{"en":"Graph quadratic functions and their key features, building on linear functions from Mathematics I.","es":"Representar funciones cuadráticas y sus características principales, partiendo de las funciones lineales de Matemáticas I."}},{"targetIds":["HSF-IF.C.7b"],"extent":"full","source":{"sourceId":"appendix-a","pages":[64]},"scope":{"en":"The listed substandard includes square root, cube root, and piecewise-defined functions. Instructional notes emphasize comparisons of absolute value, step, and piecewise-defined functions with linear, quadratic, and exponential functions, attending to domain, range, and usefulness.","es":"El subestándar enumerado incluye funciones raíz cuadrada, raíz cúbica y definidas a trozos. Las notas didácticas destacan la comparación de funciones de valor absoluto, escalonadas y definidas a trozos con funciones lineales, cuadráticas y exponenciales, atendiendo al dominio, recorrido y utilidad."}}]'::jsonb),
    ('grade-10', 'HSF-IF.C.7b', 'listed', '[{"targetIds":["HSF-IF.C.7a"],"extent":"full","source":{"sourceId":"appendix-a","pages":[64]},"scope":{"en":"Graph quadratic functions and their key features, building on linear functions from Mathematics I.","es":"Representar funciones cuadráticas y sus características principales, partiendo de las funciones lineales de Matemáticas I."}},{"targetIds":["HSF-IF.C.7b"],"extent":"full","source":{"sourceId":"appendix-a","pages":[64]},"scope":{"en":"The listed substandard includes square root, cube root, and piecewise-defined functions. Instructional notes emphasize comparisons of absolute value, step, and piecewise-defined functions with linear, quadratic, and exponential functions, attending to domain, range, and usefulness.","es":"El subestándar enumerado incluye funciones raíz cuadrada, raíz cúbica y definidas a trozos. Las notas didácticas destacan la comparación de funciones de valor absoluto, escalonadas y definidas a trozos con funciones lineales, cuadráticas y exponenciales, atendiendo al dominio, recorrido y utilidad."}}]'::jsonb),
