    ('grade-10', 'HSF-IF.C.8b', 'listed', '[{"targetIds":["HSF-IF.C.8a","HSF-IF.C.8b"],"extent":"full","source":{"sourceId":"appendix-a","pages":[64]},"scope":{"en":"Use equivalent quadratic and exponential forms; connect coefficients and roots, factoring, and completing the square, and extend Mathematics I''s work with integer exponents.","es":"Utilizar formas equivalentes cuadráticas y exponenciales; conectar coeficientes y raíces, factorización y completar el cuadrado, y ampliar el trabajo de Matemáticas I con exponentes enteros."}}]'::jsonb),
