    ('grade-10', 'HSF-BF.A.1b', 'listed', '[{"targetIds":["HSF-BF.A.1a","HSF-BF.A.1b"],"extent":"limited","source":{"sourceId":"appendix-a","pages":[64]},"scope":{"en":"Focus function building on situations with a quadratic or exponential relationship.","es":"Centrar la construcción de funciones en situaciones con una relación cuadrática o exponencial."}}]'::jsonb),
